window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q11"]=window.__LIBQ["the-gioi-hoan-my"]["q11"]||{};window.__LIBQ["the-gioi-hoan-my"]["q11"]["cotTruyen"]=[{"chuong":1001,"tieuDe":"Chiến Ninh Xuyên","tomTat":"Thạch Hạo xông vào thiên kiếp của Ninh Xuyên, dùng Luân Hồi quyền xuyên phá cảnh tượng vũ trụ do Thiên đồ tạo ra và khiến đối thủ chịu ảnh hưởng của sức mạnh thời gian. Ninh Xuyên thu các ngôi sao thành đại vũ trụ tinh đồ để trấn áp, nhưng Thạch Hạo vận chuyển Côn Bằng pháp, kết hợp Thái âm với Thái dương và phá thủng thế công. Ninh Xuyên tiếp tục phô bày Kỳ Lân quyền bẩm sinh, buộc Thạch Hạo dùng Liễu Thần pháp trực diện chống đỡ. Cuộc giao tranh đánh động chân long, thiên phượng và các sinh linh lôi điện, trong khi kiếm khí từ Trảm Tiên đài khiến cả hai cùng bị thương. Ninh Xuyên dùng Cửu Ngũ Chí Tôn thiên công, còn Thạch Hạo lấy Bát Cửu Thiên Công thống ngự nhiều bảo thuật để đối đầu, khiến đôi bên đều trọng thương nhưng Thạch Hạo chiếm ưu thế nhờ thân thể. Trong lúc Ninh Xuyên suy yếu, Thạch Hạo thu lấy phần lớn Lôi Kiếp dịch trước khi lôi kiếp tầng thứ mười và Lôi trì biến mất. Ninh Xuyên tức giận xông lên lần nữa, còn Thạch Hạo quyết định tiếp tục giao chiến để lấy mạng đối thủ."},{"chuong":1002,"tieuDe":"Quét Ngang Tiên Cổ","tomTat":"Sau khi thiên kiếp kết thúc, Ninh Xuyên quyết chiến với Thạch Hạo vì phần lớn Lôi Kiếp dịch của mình đã bị đoạt, còn các Giáo chủ bản địa cũng chia thành hai phe hỗn chiến quanh số thần dịch. Thạch Hạo và Ninh Xuyên giao phong khoảng hai nghìn chiêu bằng nhiều bảo thuật mạnh, trong khi tin tức lan khắp Tiên cổ và thu hút đông đảo thiên tài cùng dân bản địa đến quan sát. Chờ lúc Ninh Xuyên chuẩn bị đòn mạnh nhất, Thạch Hạo bất ngờ phát động miễn dịch pháp lực, khiến bảo thuật của đối phương tạm thời mất hiệu lực rồi liên tiếp dùng Côn Bằng quyền, bảo thuật Liễu Thần và bảo thuật Lôi Đế gây trọng thương. Ninh Xuyên buộc phải đánh thức xương tay Chân Tiên trong tay trái, dùng sức mạnh Tiên đạo phá trạng thái miễn dịch pháp lực và tạo ra công kích khiến các Giáo chủ biến sắc. Tuy nhiên, tiên cốt tiêu hao quá nhiều tinh khí, thần lực và đạo hạnh, đồng thời làm cánh tay hắn gãy nát. Nhận thấy mình có nguy cơ bị giết, Ninh Xuyên dùng xương tay xuyên thủng hư không để đào tẩu bất chấp phong cấm của Giáo chủ. Thạch Hạo lập tức truy sát, khiến toàn Tiên cổ chấn động và được nhìn nhận là đã có sức mạnh quét ngang nơi này."},{"chuong":1003,"tieuDe":"Tiên Cổ Bị Xé Rách","tomTat":"Ninh Xuyên mang trọng thương tháo chạy trước sự truy sát của Thạch Hạo, khiến thần thoại bất bại suốt sáu thế của Lục Quan vương sụp đổ. Thạch Hạo dùng cành liễu, lôi điện, Vạn Linh đồ và Động thiên duy nhất liên tục áp đảo đối thủ, trong khi Ninh Xuyên phản kích bằng xương tay Chân Tiên và Vòng xuyến Lục Đạo Chí Tôn. Không thể thoát bằng giao chiến trực diện, Ninh Xuyên phối hợp với cường giả ngoại giới công kích khe nứt, xé mở Tiên cổ rồi xông ra ngoài. Thạch Hạo trở về Hồn đạo, chia Lôi Kiếp dịch cho bốn Giáo chủ để nâng lực lượng hỗ trợ mình lên chín người. Tiên cổ sau đó hoàn toàn nối liền với ngoại giới, khiến các Giáo chủ và Thiên Thần tràn vào, còn ba ngàn cánh hoa đại Đạo đưa toàn bộ thiên tài sống sót rời khỏi nơi thí luyện. Thạch Hạo bị ánh sáng truyền tống tách khỏi chín Giáo chủ hộ tống và xuất hiện tại cửa ra đã bị các Giáo chủ đối địch phong tỏa. Những người này nhắm tới tiên chủng, tiên kinh, Nghịch long lân cùng các tạo hóa khác trên người hắn, đẩy hắn vào nguy cơ bị vây bắt."},{"chuong":1004,"tieuDe":"Giáo Chủ Vây Kín","tomTat":"Đóa hoa Tiên đạo mở ba ngàn cánh cửa đưa các thiên tài rời Tiên cổ, nhưng nhiều Giáo chủ đã giáng lâm, dùng thần niệm dò xét và dựng hàng chục đại trận quanh lối ra để săn tìm Hoang. Thập Quan vương giết người nhận ra mình rồi thả Vong linh hải gây hỗn loạn, còn Trích tiên dùng sừng Thiên Giác Nghĩ xé khóa hư không để đào tẩu. Trong âm vụ, Thạch Hạo và Thiên yêu Cát Tiềm dùng Thiên Nhãn nhận ra nhau; Thạch Hạo đánh lạc hướng đối phương rồi kích hoạt Phá Giới phù chạy trốn. Ứng Long dẫn Nhai Tí, Cửu đầu điểu cùng các sinh linh Cấm khu tập kích, bắt Cát Tiềm và nhiều thiên tài, khiến đại chiến với các Giáo chủ bùng phát. Dù đã xuyên đi rất xa, Thạch Hạo vẫn bị hệ thống đại trận ép khỏi hư không và bị một Thiên Thần phát hiện thân phận. Người Hộ Đạo của Thiên Nhân tộc thừa nhận ân nghĩa của hắn nhưng vẫn quyết giết để trừ hậu hoạn, trong khi Phó Giáo chủ và Giáo chủ Thiên quốc cũng kéo tới tranh quyền xử trí. Minh chủ ngự trên Bạch cốt sơn giáng lâm, coi thường cảnh giới Thánh tế của Thạch Hạo, rồi người của Kiếm cốc, Hỏa Vân động và Yêu Long đạo môn tiếp tục xuất hiện, hoàn tất vòng vây nhiều phía quanh Hoang."},{"chuong":1005,"tieuDe":"Sư Môn Tái Hiện","tomTat":"Thập Quan vương dùng cây non Thế Giới thụ xuyên phá các trận pháp phong tỏa rồi được một người của Đế tộc dùng cầu đá trắng đưa khỏi chiến trường. Sau khi hắn rời đi, nhiều Giáo chủ thuộc các đạo thống lớn đồng loạt vây giết Thạch Hạo nhằm đoạt Vạn Linh đồ, Tiên chủng, Đạo thư ngọc thạch và tiên kiếm Đại La, còn Minh chủ muốn lấy thi thể hắn luyện thành sinh linh Minh thổ. Thạch Hạo dùng Vạn Linh đồ và Nghịch long lân chống đỡ nhưng vẫn bị dư chấn, thần âm đại đạo, kiếm khí cùng nhiều đòn đánh khác làm trọng thương; đường hầm thời gian dùng để đào thoát cũng bị trận pháp chặn đứng. Trong tuyệt cảnh, hắn kích hoạt cổ phù lấy từ phế tích có Tam thế đồng quan, phóng thần quang xuyên thủng ông lão La Phù chân cốc, nhưng tấm phù lập tức xuất hiện vết rạn. Khi các Giáo chủ tiếp tục ép Thạch Hạo tới bờ vực sống còn, Tề Đạo Lâm mang thi thể hậu bối của nhiều giáo tới và tuyên bố sẽ trả thù bất kỳ thế lực nào giết đệ tử mình. Côn Bằng tử sau đó hiện thân, công khai bảo hộ Hoang và thả xuống hàng loạt thi thể Thiên Thần vừa bị mình giết, khiến cục diện vây giết xuất hiện biến chuyển lớn."},{"chuong":1006,"tieuDe":"Vui Sướng","tomTat":"Thạch Hạo bị ba ngàn cánh hoa đại Đạo giữ lại trong tình trạng trọng thương, nhưng Tề Đạo Lâm và Sinh linh Bất diệt kịp thời xuất hiện bảo vệ hắn. Hai cường giả công khai công nhận chiến tích quét ngang Tiên cổ và tiềm lực bước vào hàng ngũ chí cường của hắn. Trước những lời đe dọa từ Hỏa Vân động, Thiên Nhân tộc, Minh chủ, Thần miếu và Đọa Ma lĩnh, Tề Đạo Lâm không lùi bước mà tái khẳng định lời thề bảo vệ đệ tử. Ông chính thức tuyên bố Thạch Hạo là đệ tử chân chính của Cung điện Chí Tôn và đặt hy vọng phục hưng đạo thống lên hắn. Nhân vật số hai của Tiên điện bước ra từ điện đồng để ngăn cản nhưng bị Sinh linh Bất diệt chặn lại và đe dọa trấn áp. Trong khi đó, Nguyệt Thiền cùng cậu nàng đề nghị Bổ Thiên giáo cứu Hoang để kết thiện duyên, còn Ma nữ cũng hỏi vị chí tôn của Tiệt Thiên giáo có nên can thiệp hay không. Chương kết thúc khi cả hai thế lực vẫn chưa công bố quyết định."},{"chuong":1007,"tieuDe":"Côn Bằng Tử","tomTat":"Tuyết Lâm cầu lão tổ bộ tộc Yêm cứu Thạch Hạo, trong khi Tào Vũ Sinh thúc giục vị sư phụ mơ màng của mình tỉnh dậy tham chiến. Tề Đạo Lâm bảo vệ Thạch Hạo, đánh người Hộ Đạo Thiên Nhân tộc trọng thương, chém lấy một sừng và một tảng thịt từ bản thể trâu lớn rồi giao cho đệ tử. Hỏa Vân động, Tiên điện, Đọa Thần lĩnh cùng nhiều cường giả chí cao hợp lực vây giết, nhưng Tề Đạo Lâm dùng Bát Cửu Thiên Công tự sáng tạo chống quần hùng và đánh Ma tôn hộc máu. Sinh linh Bất diệt xông qua thế vây, giết phó môn chủ Yêu Long đạo môn đến hình thần đều diệt rồi tiếp tục đối đầu Cốc chủ Kiếm cốc. Khi ông gọi thứ thân tới, Thạch Hạo nhận ra đó là lão già nát rượu của Côn môn từng bán tín vật Tiên cổ cho mình. Chủ nhân Thiên quốc trực tiếp gọi Sinh linh Bất diệt là Côn Bằng tử và muốn lĩnh giáo chân thân của hắn. Giáo chủ Tây Phương giáo cũng tới chiến trường, khiến cuộc vây chiến tiếp tục mở rộng quanh thời điểm chủ thân và thứ thân của Côn Bằng tử cùng xuất hiện."},{"chuong":1008,"tieuDe":"Cuộc Chiến Giáo Chủ","tomTat":"Thân thế của sinh linh Bất Diệt được xác nhận: hắn chính là Côn Bằng tử, con trai của Côn Bằng, khiến Thạch Hạo và các cường giả hiện diện chấn động. Thứ thân Côn Bằng tử tiết lộ trận chiến năm xưa còn có hai sinh linh bí ẩn tham dự, đồng thời ám chỉ họ là chỗ dựa phía sau tai họa tại Biên hoang và bí mật ấy có thể liên quan đến Tội huyết nhất mạch. Chủ nhân Thiên quốc mở màn cuộc vây giết, kéo theo cốc chủ Kiếm cốc, môn chủ Yêu Long đạo môn, chủ nhân Ma Quỳ viên, chủ nhân Thái Dương thần cung cùng nhiều bá chủ đồng loạt hợp kích. Côn Bằng tử giết hổ bạc, xé bị thương môn chủ Yêu Long đạo môn và xé tan tê giác trắng, trong khi Cửu Diệt Bất Tử thuật giúp hắn sống sót rồi hồi phục sau những đòn đủ sức diệt một Giáo chủ thông thường. Thứ thân của hắn vừa dùng áo nghĩa Côn Bằng đối đầu Long châu vừa tiếp tục xung trận, sau đó phóng phù văn từ mắt xuyên thủng mi tâm một Giáo chủ. Kim Sí Đại bằng và Thanh Thiên bằng bất chấp lời cảnh cáo của chư giáo, lao vào chiến trường trợ giúp Côn Bằng tử. Cuối chương, một người chưa rõ danh tính cất tiếng đáp lại chủ nhân Thiên quốc, còn từng cành liễu vàng từ bầu trời hạ xuống, báo hiệu một biến số mới xuất hiện."},{"chuong":1009,"tieuDe":"Liễu Thần Tái Hiện","tomTat":"Kim Sí Đại bằng và Thanh Thiên bằng tới trợ giúp Côn Bằng tử, trong khi một cành liễu vàng xuất hiện khiến nhiều Giáo chủ từng xuống hạ giới kinh hãi. Huyết Bức không tin Liễu Thần trở lại nên dùng thần thông sóng âm khiêu khích, nhưng bị một lá vàng xuyên thủng mi tâm và giết chết. Cô Kiếm Vân, Ninh Xuyên cùng Ngân Huyết ma thụ sau đó xác nhận đây chỉ là đoạn cành cổ tổ Tế Linh được dân bản địa Tiên cổ bảo vệ, không phải cây liễu hoàn chỉnh. Chín Giáo chủ di dân Tiên cổ tới đứng về phía sinh linh Bất Diệt, song Chủ nhân Thiên quốc, Minh chủ và Cốc chủ Kiếm cốc vẫn đòi xử lý Hoang, khiến cuộc chiến bùng phát trở lại. Chí tôn đời thứ nhất của Tiên điện thức tỉnh, điều khiển Tiên điện đồng lao tới và tuyên bố trấn áp sinh linh Bất Diệt, dân bản địa Tiên cổ cùng đạo tràng Chí tôn. Đúng lúc ấy, Liễu Thần thật sự xuất hiện từ sâu trong khu không người giữa dị tượng chư thiên thần ma cúi chào. Liễu Thần đánh bật Tiên điện đồng, thu đoạn cành vàng, bẻ gãy thần kiếm và đánh Cốc chủ Kiếm cốc trọng thương, rồi xuyên thủng nhiều tay của Giáo chủ Tây Phương giáo. Cuối cùng, Liễu Thần lại vỗ một chưởng khiến Tiên điện đồng lao mạnh xuống mặt đất."},{"chuong":1010,"tieuDe":"Phong Thái Của Liễu Thần","tomTat":"Liễu Thần trở về từ sâu trong khu không người, một chưởng đánh điện đồng cổ xuống đất, xuyên thủng nhiều tầng đại trận và kích thương các Giáo chủ đang vây công. Quanh hình người áo trắng của nó hiện ra ba ngàn thế giới, khiến Thạch Hạo vừa xúc động vừa băn khoăn liệu đây có phải Liễu Thần chân chính. Chí tôn Tiên điện thức tỉnh điện đồng, nhận ra Liễu Thần là tiên căn còn sót lại từ kỷ nguyên trước và kêu gọi liên quân tiêu diệt nó. Khi các Giáo chủ nhất quyết đòi giữ Thạch Hạo và ép Tề Đạo Lâm giao đồ vật, Liễu Thần chấm dứt thương lượng rồi nhận chiến. Chí tôn Tiên điện cùng nhiều Giáo chủ đồng loạt ra tay, trong khi Côn Bằng tử và Tề Đạo Lâm chống trả liên quân. Liễu Thần dùng cành vàng phá kiếm gãy, giết cốc chủ Kiếm cốc, sau đó phá Lưỡi hái tử thần và diệt nguyên thần một cường giả Minh thổ. Cuối cùng, hàng trăm nghìn cành liễu trói điện đồng, biến tòa điện thành vũ khí và đập chết một Giáo chủ Đằng Xà tộc ngay tại trận."},{"chuong":1011,"tieuDe":"Trảm Các Lộ Giáo Chủ","tomTat":"Liễu Thần dùng pháp lực cùng vô số cành vàng áp chế điện đồng của Tiên điện, rồi biến chí bảo này thành vũ khí nghiền chết Thú mắt vàng và Giáo chủ Thiên Hạt. Chí tôn Tiên điện kích phát lớp gỉ đồng nguyền rủa, khiến mưa sáng xanh lục ăn mòn cành vàng và giúp điện đồng thoát khỏi khống chế. Liễu Thần dồn toàn bộ nguyền rủa vào một cành duy nhất rồi thiêu nổ nó, sau đó đánh tan Nhân Tiên do đối phương kết ấn hiển hóa. Khi chủ nhân Yêu Long đạo môn kêu gọi quần hùng hợp lực, hàng trăm cành vàng bẻ gãy sừng, phá hủy thân thể và xuyên thủng nguyên thần của hắn. Không tiếp tục tranh quyền điều khiển điện đồng, Liễu Thần bước thẳng vào bên trong chí bảo để truy sát chí tôn Tiên điện. Quần hùng chứng kiến nhiều Giáo chủ liên tiếp bỏ mạng nên càng thêm khiếp sợ trước uy thế áp đảo của Liễu Thần."},{"chuong":1012,"tieuDe":"Giáo Chủ Hỗn Chiến","tomTat":"Liễu Thần xông vào điện đồng Tiên điện, phá tan Bất Tử điểu chín đầu do cốt văn hóa thành và đánh xuyên giả thân đang ngồi xếp bằng. Quan tài thủy tinh sau đó nổ tung, để lộ chân thân chí tôn Tiên điện, kẻ đã tự phong kín để duy trì sức sống và định dùng điện đồng luyện hóa Liễu Thần. Bị nhốt trong chí bảo, Liễu Thần cưỡng ép đánh nghiêng điện đồng vào đội hình các Giáo chủ, khiến chí tôn Tiên điện lo sợ bảo vật đổi chủ và phải mở phong ấn để quyết chiến bên ngoài. Giữa lúc hai bên giao phong, nhiều cường giả chuyển sang công kích Thạch Hạo, nhưng Côn Bằng tử, Thần chủ Khổng Tước, Thanh Thiên bằng, Kim Sí Đại bằng và chín Giáo chủ Tiên cổ cùng đứng ra bảo vệ cậu. Lão Quy trắng như tuyết viện dẫn biến loạn tại Biên Hoang để khuyên đình chiến, song chí tôn Tiên điện từ chối. Một bóng người bí ẩn điều khiển chuông cổ phối hợp với điện đồng vây công Liễu Thần, trong khi âm thanh thờ cúng từ hàng vạn cành liễu khiến các Giáo chủ Tiên cổ xác nhận nó là cổ tổ Tế Linh. Cuối cùng, chữ Chung hiện ra bên cạnh chữ Vô trên thân chuông, làm lộ tên Vô Chung và dẫn tới lời đồn rằng Đạo này còn cần áo nghĩa Thủy để trở nên trọn vẹn."},{"chuong":1013,"tieuDe":"Vô Chung","tomTat":"Chuông Vô Chung tập trung tiếng chuông và phù văn áp chế Liễu Thần, khiến các Giáo chủ đối địch nhìn thấy cơ hội đảo ngược chiến cuộc. Giáo chủ Tây Phương giáo tiết lộ chiếc chuông từng thuộc về tuyệt thế chí tôn Vô Chung, người đã vô địch một thời đại từ hơn một kỷ nguyên trước. Khi hai chữ Vô Chung cùng phát sáng, một lĩnh vực thời gian hỗn loạn hình thành, trục xuất Liễu Thần về phía hư vô trong lúc cổ tổ Tiên điện và nhiều Giáo chủ tiếp tục liên thủ công kích. Liễu Thần chịu tổn thất nhiều cành lá vàng nhưng sau đó phá tan lĩnh vực quy tắc, làm chủ chuông và cổ tổ Tiên điện cùng bị phản chấn. Trước sự ngoan cố của phe vây công, Liễu Thần để ba ngàn thế giới hóa thành dấu ấn giáp trụ và tiến vào Vô Địch đạo. Nó dùng tay không phá nát đỉnh cổ hộ thể, giết một Giáo chủ rồi đánh trọng thương chủ chuông Vô Chung cùng cổ tổ Tiên điện. Nhận ra hai chủ lực đã thất bại, phe đối địch xin dừng chiến nhưng Liễu Thần cự tuyệt và tuyên bố cuộc sát phạt chưa kết thúc."},{"chuong":1014,"tieuDe":"Ngừng Chiến","tomTat":"Lão Giáo chủ Tiên điện xin dừng tay nhưng Liễu Thần vẫn dùng Chân Hoàng ấn áp chế điện đồng, đồng thời lấy lá liễu hóa Côn Bằng phong tỏa chuông Vô Chung và đánh trọng thương chủ nhân chiếc chuông. Khi hai cường giả sắp bị giết, một pháp chỉ mang văn tự kỷ nguyên Tiên cổ cùng chiếc búa cổ không trọn vẹn từ vực ngoại xuất hiện cầu tình, khiến Liễu Thần tạm tha họ với điều kiện phải có biểu hiện tại Biên Hoang. Liễu Thần sau đó chuyển sang chiến trường khác, chất vấn quyền định danh đời sau tội huyết và giết ba Giáo chủ từng dùng danh xưng ấy đối với Thạch Hạo, trong khi Côn Bằng tử cũng hạ sát thêm một đối thủ cấp Giáo chủ. Người bí mật tiết lộ với Thạch Hạo rằng thân thể hiện diện chỉ là dấu ấn chiến đấu lưu trong đoạn cành liễu được dân bản địa Tiên cổ cúng tế, còn chân thân đã bước qua cánh cửa Nguyên Thủy và có thể không bao giờ trở lại. Thạch Hạo đau buồn nhưng quyết tâm sẽ tới thế giới bên kia tìm Liễu Thần. Khi các cường giả trung lập và Giáo chủ các bên tới bày tỏ lập trường, Liễu Thần chính thức kết thúc trận chiến, công khai nhận Thạch Hạo là đệ tử và cảnh cáo mọi đạo thống tại ba ngàn châu rằng kẻ nào lấy lớn hiếp nhỏ hoặc mưu hại hắn sẽ bị xem là tuyên chiến và có thể bị diệt sạch."},{"chuong":1015,"tieuDe":"Dư Âm","tomTat":"Lời chiêu cáo của Liễu Thần gây chấn động thiên hạ, buộc Kiếm Cốc và Yêu Long đạo môn phải nén ý định báo thù, dù Thạch Hạo biết người che chở mình chỉ là một dấu ấn chiến đấu. Bằng hữu và nhiều nhân vật lớn lần lượt tới chúc mừng, trong đó Thần chủ Khổng Tước gọi Liễu Thần là sư tôn và nhận Thạch Hạo làm tiểu sư đệ. Thạch Hạo vẫn kính trọng Tề Đạo Lâm, cảm tạ Côn Bằng tử, đồng thời chứng kiến Ma nữ trêu chọc Nguyệt Thiền và cậu của nàng đề nghị để hắn ở rể Bổ Thiên giáo. Hắn đoàn tụ với Thạch Tử Lăng, Tần Di Ninh và Tần Hạo nhưng từ chối gia nhập Tần tộc, tuyên bố sẽ luôn giúp đỡ em trai và âm thầm cảnh giác với Bất Lão Thiên tôn. Thạch Hạo còn trịnh trọng nhờ người Tần tộc tìm A Man, cô gái từng chăm sóc hắn thuở nhỏ nhưng đã thất lạc sau khi lên thượng giới. Tào Vũ Sinh và Ma nữ báo tin các cường giả vực ngoại đang áp đảo tu sĩ ba ngàn châu, trong khi nhiều cổ giới chuẩn bị thành lập Thánh viện, Tiên viện và thư viện Thiên Thần. Cuối cùng, Liễu Thần mang Thạch Hạo rời đi cùng Côn Bằng tử và Tề Đạo Lâm."},{"chuong":1016,"tieuDe":"Thế Giới Trong Tâm Tư Của Liễu Thần","tomTat":"Liễu Thần tiết lộ với Thạch Hạo rằng thế giới quê cũ của mình đã bị thiêu trụi, toàn bộ cố nhân đều chết và chân thân sau khi bước qua cánh cửa Nguyên Thủy có thể đã gặp bất trắc. Nó cảnh báo rằng ngay cả vô địch tại Cửu Thiên Thập Địa cũng chưa đủ xoay chuyển đại cục, nhưng Thạch Hạo vẫn quyết chí mạnh lên và cùng nó chinh chiến. Liễu Thần chỉ Biên Hoang là chặng đầu trên con đường tìm tới thế giới phía địch thủ, nơi Thạch Hạo không chỉ phải trấn thủ mà còn phải tìm cách chủ động đánh sang. Khi dấu ấn sắp tan rã, Liễu Thần dùng sức mạnh cuối cùng thi triển một đại thần thông, quấy nhiễu quy tắc thiên địa và gọi ra dòng sông thời gian. Thạch Hạo nhìn thấy cố nhân dần già nua, rồi thấy bản thân trưởng thành cô độc đứng trên vạn đạo giữa một thế gian không còn sinh linh hay người quen. Phía sau bản thân tương lai của hắn chỉ còn một cành liễu cháy đen đã gãy và chết, nhưng Thạch Hạo không chấp nhận kết cục ấy, đồng thời thề sẽ xoay chuyển toàn bộ tương lai."},{"chuong":1017,"tieuDe":"Danh Chấn Ba Ngàn Châu","tomTat":"Sau khi chứng kiến viễn cảnh bản thân cô độc trên đỉnh Thần đạo, Thạch Hạo thề trở thành biến số để thay đổi tương lai. Liễu Thần khẳng định kết cục vẫn có thể thay đổi, khuyên hắn phải tự mở con đường tu hành riêng rồi tiêu tán thành ánh sáng tẩm bổ thiên địa. Tề Đạo Lâm quyết định tiếp tục tiến sâu vào khu vực không người tìm Cung điện Chí Tôn, còn Côn Bằng tử động viên Thạch Hạo trước khi rời đi. Thạch Hạo vượt qua tâm trạng nặng nề và trở về ba ngàn châu, nơi chiến tích của Hoang tại Tiên cổ đã khiến hắn danh chấn thiên hạ. Hắn bí mật tới Ma châu đoàn tụ với Đại ma thần, kể lại chiến tích và ép tổ phụ nhận một trái Thiên Thần quả. Trong lúc ấy, một khách trẻ tuổi từ vực ngoại công khai coi thường Hoang và đòi giao chiến với người mạnh nhất Tiên cổ, giữa lúc Liên minh Cửu Thiên Thập Địa chuẩn bị thành lập ba viện tuyển chọn kỳ tài. Sau vài ngày ở bên tổ phụ, Thạch Hạo tiếp tục lên đường tìm kiếm sức mạnh và tới vùng Hỏa Tang tại Hỏa châu để tìm dấu vết cố nhân."},{"chuong":1018,"tieuDe":"Như Trước Hỏa Tang","tomTat":"Thạch Hạo trở lại Hỏa Tang lâm, lần theo ký ức tìm đến nơi ở cũ của Hỏa Linh Nhi nhưng chỉ thấy tiểu viện đã bị thiêu thành tro. Một mảnh cốt thuẫn vỡ dính máu khô khiến hắn lo nàng gặp nạn, song cuộc tìm kiếm kéo dài một ngày một đêm vẫn không đem lại thêm manh mối. Hắn tới thành Ly Hỏa, cưỡng ép dò biển ý thức của thành chủ và biết nhóm người từng tiến vào khu rừng vẫn lưu lại quanh đây. Trở về Hỏa Tang lâm, Thạch Hạo bắt được nhóm tu sĩ canh giữ và buộc họ khai rằng Kiếm cốc, Hỏa Vân động, La Phù chân cốc cùng Thiên Nhân tộc từng phái người truy bắt Hỏa Linh Nhi. Hỏa Hoàng đã trở về từ hạ giới và đưa con gái rời khỏi chỗ ở cũ trước khi những kẻ truy bắt tới nơi. Sau khi giết sạch nhóm tu sĩ và quyết định sẽ tìm các thế lực đứng sau tính sổ, Thạch Hạo tiếp tục tìm kiếm trong rừng. Đến ngày thứ tư, hắn nhận ra Hỏa Linh Nhi trong hình dáng một thiếu nữ hái dâu đã đổi dung mạo và biết nàng vẫn luôn ở lại Hỏa Tang lâm chờ mình."},{"chuong":1019,"tieuDe":"Tương Phùng","tomTat":"Thạch Hạo nhận ra cô gái mặc vải bố giữa rừng Hỏa Tang chính là Hỏa Linh Nhi và tiến đến gặp nàng. Hỏa Linh Nhi cho biết nàng vẫn ở lại chờ hắn dù có người truy tìm và nơi ở cũ từng bị đốt cháy. Bên một dòng suối, Thạch Hạo dùng xác Thanh Giao thuần huyết cấp Thiên Thần làm thức ăn, khiến nàng kinh ngạc trước thực lực hiện tại của hắn. Hắn kể lại hành trình tranh bá trong Tiên cổ, bao gồm những lần giao chiến với các vương giả, vượt thiên kiếp, hoàn thành Thánh tế và giành vị trí đứng đầu. Biết khoảng cách tu vi giữa hai người đã quá lớn, Hỏa Linh Nhi lo mình chỉ có thể ở lại phía sau khi hắn tiến vào thế giới rộng lớn hơn. Thạch Hạo nắm tay nàng, khẳng định không coi trọng sự chênh lệch ấy và hứa sẽ đưa nàng cùng xông lên cửu tiêu."},{"chuong":1020,"tieuDe":"Cùng Nhau Du Ngoạn","tomTat":"Hỏa Linh Nhi lo tu vi và tuổi thọ của mình không đủ để đồng hành lâu dài với Thạch Hạo, còn hắn trấn an nàng và bộc lộ chí hướng chinh chiến Biên Hoang, truy tìm bí mật về sự diệt vong của Tiên cổ. Thạch Hạo lấy cây thần trồng trong Vạn Vật thổ ra, xin một Thiên Thần quả rồi trao cho Hỏa Linh Nhi. Thần quả gột rửa và tái tạo thân thể nàng, mở hoàn toàn huyết thống Chu Tước, giúp nàng trực tiếp bước vào cảnh giới Thiên Thần sau một ngày một đêm. Sau khi nỗi lo trước mắt được hóa giải, hai người cùng du ngoạn núi sông trong thiên hạ. Trong lúc đó, Lâm Thiên và các Thiên Thần trẻ tuổi từ vực ngoại liên tiếp đánh bại những kỳ tài trở về từ Tiên cổ, công khai chê bai ba ngàn châu và gọi Trích tiên, Hoang ra giao chiến. Nhớ lại việc Thiên Nhân tộc từng phát tán tin tức về Hỏa Tang lâm và tham gia truy đuổi Hỏa Linh Nhi, Thạch Hạo đưa nàng tới Thiên châu để đòi một lời giải thích. Khi đến gần địa bàn đối phương, hắn tuyên bố mình đã trở lại."},{"chuong":1021,"tieuDe":"Giá Lâm Tổ Địa Thiên Nhân Tộc","tomTat":"Thạch Hạo đưa Hỏa Linh Nhi trở lại quốc thổ Thiên Nhân tộc để giải quyết món nợ từng bị lấy oán báo ân, giam giữ và tra hỏi bảo thuật. Hắn đánh thức Đả Thần Thạch đang luyện hóa nhiều kỳ thạch; nhờ hiểu biết trận văn của nó cùng các phù lục đã chuẩn bị, cả nhóm vượt qua cổ trận bao phủ tổ địa. Thạch Hạo thả Hoàng điệp và Đả Thần Thạch, cùng Hỏa Linh Nhi thu gom lượng lớn bảo dược, khiến lực lượng canh giữ phải truy tìm kẻ xâm nhập. Khi một nhóm Chân Thần dùng cốt kính phát hiện họ và phát động lôi điện, Thạch Hạo hấp thu toàn bộ đòn đánh rồi dùng một chỉ đánh tàn phế cả nhóm nhưng không giết chết. Hắn công khai tuyên bố tới tính sổ và yêu cầu các Thiên Thần của Thiên Nhân tộc ra chịu chết, khiến tin Hoang đánh tới lan khắp tổ địa. Thiên Nhân tộc vốn đã bất an vì người Hộ Đạo trọng thương sắp chết nay càng rơi vào hoảng loạn. Trên Thiên Chi Thành, Vân Hi nhận ra Thạch Hạo và nhìn thấy Hỏa Linh Nhi mặc áo đỏ đứng bên cạnh hắn."},{"chuong":1022,"tieuDe":"Thiên Chi Thành Tiếc Nuối","tomTat":"Thạch Hạo cùng Hỏa Linh Nhi đánh tới Thiên Chi Thành, khiến Vân Hi trên tường thành nhận ra họ và cay đắng nhớ lại ân oán giữa hắn với Thiên Nhân tộc. Hắn đánh phế nhóm Chân Thần canh giữ, phá hủy bảo cụ của họ rồi đoạt cốt kính dò địch giao cho Hỏa Linh Nhi. Mạc La bước ra trên con đường vàng do thành trì phóng ra, được khí lành gia trì và che chở, nhưng Thạch Hạo dùng Nghịch long lân cắt đứt mối liên hệ ấy. Mất sự bảo hộ, Mạc La tung lưới cát tinh thần cùng nhiều bảo thuật chống trả nhưng bị bảo thuật Lôi Đế phá tan. Thạch Hạo chém đầu Mạc La và đánh nổ nguyên thần, khiến vị Thiên Thần hoàn toàn diệt vong ngay trước tổ địa. Toàn thành chấn động khi nhận ra Hoang đã trở về báo thù, còn một số cao tầng tiếc nuối vì từng biến thiên kiêu có ba luồng tiên khí thành đại địch. Cuối chương, Thạch Hạo đứng bên ngoài Thiên Chi Thành, một mình gọi toàn bộ Thiên Thần và người Hộ đạo của Thiên Nhân tộc ra ứng chiến."},{"chuong":1023,"tieuDe":"Đe Dọa","tomTat":"Cao tầng Thiên Nhân tộc vừa hối tiếc vì từng bỏ lỡ Thạch Hạo vừa phẫn nộ khi hắn công khai khiêu chiến ngay ngoài tổ địa, nhưng họ không dám tùy tiện giết hắn vì e ngại Liễu Thần báo thù. Sau khi tranh luận, họ khởi động trận pháp và điều động toàn bộ Thiên Chi Thành hóa thành pháp khí khổng lồ truy kích Thạch Hạo cùng Hỏa Linh Nhi. Thạch Hạo đưa Hỏa Linh Nhi né tránh rồi lấy Vạn Linh đồ phòng ngự, khiến hình bóng vạn linh thái sơ hiện ra và hóa giải cốt văn cùng lực trấn áp của cổ thành. Do lão Thiên Nhân đang rời tộc tham chiến, Người Hộ đạo lại trọng thương gần chết, Thiên Nhân tộc không còn cường giả đủ sức khống chế hắn. Việc vận hành Thiên Chi Thành cũng tiêu hao quá nhiều tài nguyên, buộc cao tầng phải ngừng đối đầu và phái Vân Hi ra hỏi điều kiện để hắn rời đi. Vân Hi xấu hổ thay cho tộc mình và nhận ra Thạch Hạo đã trở nên xa cách, còn cuộc chào hỏi giữa nàng với Hỏa Linh Nhi chỉ giữ ở mức lịch sự."},{"chuong":1024,"tieuDe":"Thiên Nhân Bại Trận","tomTat":"Vân Hi thay mặt Thiên Nhân tộc đề nghị giảng hòa nhưng Thạch Hạo từ chối bồi thường, yêu cầu những tộc lão từng gây ân oán phải trực tiếp ra giải quyết. Dựa vào Vạn linh đồ, hắn chống sức trấn áp của Thiên Chi Thành và phong tỏa tổ địa đối phương nhằm làm tổn hại uy danh của đại tộc này. Sau khi tra hỏi một Chân Thần, Thạch Hạo mai phục Thích Thác, dùng tốc độ Côn Bằng đuổi kịp rồi lấy kiếm thai Đại La giết cả thân thể lẫn nguyên thần vị Thiên Thần. Người Hộ Đạo của Thiên Nhân tộc mang thương thế xuất quan truy sát nhưng Thạch Hạo nhiều lần dùng kiếm thai và Phá Giới phù thoát đi, sau đó quay lại khiêu khích năm lần để ép ông ta tiêu hao. Người Hộ Đạo cố suy tính tung tích Hoang, liên tục bị phản phệ, tổn thương bản nguyên đại đạo và chết sau khi thoáng thấy một góc tương lai chưa kịp tiết lộ. Thạch Hạo cùng Hỏa Linh Nhi an toàn rời đi, còn tin Thiên Nhân tộc mất hai Thiên Thần cùng Người Hộ Đạo nhanh chóng lan khắp thượng giới và gây chấn động lớn."},{"chuong":1025,"tieuDe":"Phong Vân","tomTat":"Người Hộ Đạo của Thiên Nhân tộc cưỡng ép dùng bảo thuật suy tính toàn bộ về Thạch Hạo, khơi dậy thiên phạt và cuối cùng hình thần đều diệt, khiến Thiên Chi Thành chìm trong đau thương. Thạch Hạo biết mình không thể xông sâu vào thành nên dẫn Hỏa Linh Nhi rời đi, trong khi chiến tích giết hai Thiên Thần và khiến Người Hộ Đạo tử vong nhanh chóng truyền khắp bốn phương. Hai người dành khoảng một tháng du ngoạn danh sơn đại xuyên, quan sát hồng trần và luyện tâm để giúp Thạch Hạo ổn định trạng thái Thánh tế. Họ tới gần Tội châu tìm Hỏa Hoàng nhưng ông đang du lịch thiên hạ, sau đó gặp lại Sói con đã trưởng thành thành cự thú có cánh và cho nó cùng lên đường. Trên hành trình, cả ba biết Đại liên minh Cửu Thiên Thập Địa sắp tuyển chọn anh tài cho Thánh viện, Tiên viện và thư viện Thiên Thần. Một cường giả trẻ tuổi vực ngoại đã liên tục đánh bại thiên tài ba ngàn châu trong vòng vài chiêu, đồng thời công khai muốn giao chiến với Thạch Hạo, Trích Tiên và Thập Quan vương. Bất chấp nỗi lo phải chia xa của Hỏa Linh Nhi, Thạch Hạo tới Thanh châu và tiến vào thành lớn nơi khách vực ngoại vừa xuất hiện để tìm hiểu tình hình."},{"chuong":1026,"tieuDe":"Tự Họp","tomTat":"Thạch Hạo và Hỏa Linh Nhi tiến vào Thanh thành, nơi đông đảo tu sĩ đang bàn luận về Cửu Thiên thập Địa và nhóm khách vực ngoại liên tiếp đánh bại cao thủ ba ngàn châu. Hai người lên tàn thể Sơn thần ở trung tâm thành, còn Thạch Hạo nhận thấy ba luồng tiên khí trong cơ thể cộng hưởng với khí tức Tiên đạo tại đây. Trong cuộc tụ hội trên núi, họ nghe các thiên kiêu nhắc lại việc Hiểu Nguyệt tiên tử từng tiến vào khu tạo hóa Tiên cổ và suýt đoạt được Ngọc thạch thư. Một nhóm tu sĩ không nhận ra Hoang nên chế nhạo Thạch Hạo, đuổi hắn xuống núi và tìm cách làm quen với Hỏa Linh Nhi. Hiểu Nguyệt cùng các cao thủ trên lầu nhận ra Thạch Hạo, lập tức xuống chào hỏi, khiến những kẻ vừa khinh thường hắn hoảng sợ. Nàng cho biết chỉ một khách vực ngoại ra tay đã áp đảo nhiều cao thủ thượng giới, còn nhóm người ấy đã chỉ đích danh muốn giao chiến với Hoang. Ngay sau đó, một luồng khí lành xé trời lao thẳng về Thanh thành, khiến toàn bộ tu sĩ đứng bật dậy nhìn về phía xa."},{"chuong":1027,"tieuDe":"Thông Tí Thần Viên","tomTat":"Một chiếc chiến xa bằng thần đồng năm màu xé rách hư không, bay vào Thanh thành và hạ xuống ngọn núi gãy màu đen. Người bước ra là Viên Thiên, một Thông Tí thần viên cảnh giới Thiên Thần đến từ vực ngoại, nhận Lâm Thiên làm chủ và được phái tới khảo nghiệm những người muốn vào Thư viện Thiên Thần. Viên Thiên khinh miệt cao thủ ba ngàn châu, bẻ gãy kèn lệnh rồi đánh trọng thương một Thiên Thần đầu mọc sừng trâu. Nó tiếp tục tự phong tu vi xuống ngang cảnh giới một Chân Thần từng vào di địa Tiên cổ, sau hơn mười chiêu liền đánh bại và xé lìa một cánh tay của người này. Hiểu Nguyệt tiên tử tự nhận không phải đối thủ nên hỏi ý Thạch Hạo. Thạch Hạo đứng ra chế giễu Viên Thiên và yêu cầu gọi Lâm Thiên tới, nhưng Viên Thiên tuyên bố hắn phải vượt qua cửa ải của mình trước."},{"chuong":1028,"tieuDe":"Chênh Lệch Quá Lớn","tomTat":"Thông Tí thần viên tức giận vì bị coi thường, dùng móng vuốt phủ hàng trăm lớp cốt văn tập kích Thạch Hạo, nhưng hắn vẫn ngồi nguyên tại chỗ và ném chén rượu cắt đứt móng vuốt của nó. Con thần viên tiếp tục thi triển Thông Tí quyền, song nắm đấm khổng lồ lại bị một chén rượu bình thường chặn cứng, khiến bàn tay và các khớp xương tổn thương nặng. Hiểu Nguyệt tiên tử cùng các tu sĩ Thanh châu nhận ra thực lực giữa Thạch Hạo và chiến phó vực ngoại này chênh lệch quá lớn. Khi Thông Tí thần viên định dùng chiến xa thần đồng năm màu trở về gọi Lâm Thiên, Thạch Hạo bắt trọn pháp khí cấp Giáo chủ, áp chế các dị tượng phản kháng và khiến nó thần phục. Nhớ tới người bạn Chu Yếm, hắn không giết con thần viên mà đánh cấm chế, ép nó làm phu xe và giam trên chiến xa. Cuối cùng, Thạch Hạo công khai chờ Lâm Thiên tới giao chiến, đồng thời tuyên bố muốn đến thư viện Thiên Thần để gặp các kỳ tài từ những cổ giới khác."},{"chuong":1029,"tieuDe":"Lâm Thiên","tomTat":"Trên ngọn núi gãy màu đen, quần hùng mong Thạch Hạo ra tay lấy lại thể diện cho Ba ngàn châu trước những cường giả trẻ tuổi vực ngoại. Thông Tí thần viên viện dẫn chủ nhân và Cửu Thiên thập Địa để uy hiếp nhưng vẫn bị Thạch Hạo bắt làm phu xe, trong khi tin tức về hậu nhân Trường Sinh giả càng khơi dậy mong muốn tìm đối thủ mạnh của hắn. Qua lời Hiểu Nguyệt tiên tử, Thạch Hạo biết di địa Tiên cổ đã thu hút nhiều đại nhân vật, song phần lớn cư dân bản địa vẫn bị nguyền rủa giữ chân. Ở một nơi khác, Lâm Thiên điều chỉnh tinh khí thần tới đỉnh cao để chuẩn bị cho cuộc quyết đấu với Ninh Xuyên, đồng thời phát hiện chiến xa năm màu của mình đã bị người khác luyện hóa. Sau khi Thông Tí thần viên tiết lộ cuộc hẹn, Thạch Hạo quyết định chỉ tới quan chiến và dẫn mọi người lên chính chiếc chiến xa ấy rời Thanh châu. Lâm Thiên cùng bốn cường giả vực ngoại tới ngọn núi gãy nhưng không tìm thấy xe, nên quyết định đánh bại Ninh Xuyên trước rồi mới truy cứu người đã lấy bảo xa. Chiến thuyền tím chở nhóm Lâm Thiên sau đó khởi hành cùng hướng với đoàn Thạch Hạo."},{"chuong":1030,"tieuDe":"Thất Bại","tomTat":"Thạch Hạo, Hỏa Linh Nhi, Hiểu Nguyệt tiên tử cùng đoàn người dùng chiến xa năm màu tới Kỳ Lân lĩnh, nơi Ninh Xuyên đang bế quan và chuẩn bị quyết chiến với Lâm Thiên. Tại đây, họ nhắc lại dị tượng khi Ninh Xuyên chào đời, dấu hoa văn giống Kỳ Lân trên đầu hắn và việc nhiều đại giáo từng tranh nhau truyền tuyệt học cho hắn. Lâm Thiên cùng bốn người trẻ tuổi tới bằng chiến thuyền tử kim, nổi giận vì chiến xa và chiến sủng của mình đã rơi vào tay Thạch Hạo, rồi dùng trường thương đen phát động công kích. Thạch Hạo lấy cảnh giới Thánh tế đối đầu Lâm Thiên ở Thiên Thần cảnh, khiến đối phương nhận ra hắn đã tu thành ba luồng tiên khí. Sau đó Ninh Xuyên xuất quan, cùng Lâm Thiên tiến vào chiến trường hư không quyết đấu và trở về với thương thế nhẹ hơn, cho thấy Lâm Thiên đã thất bại. Không cam lòng, Lâm Thiên tiếp tục đánh lén Thạch Hạo nhưng bị pháp của Liễu Thần và Lôi Đế ấn phản kích, trường thương bị chặt gãy một đoạn và bản thân hắn ho ra máu. Chương kết thúc khi Thạch Hạo nắm lấy cánh tay Lâm Thiên, định bắt sống đối phương."},{"chuong":1031,"tieuDe":"Đậu Thư Viện Thiên Thần","tomTat":"Thạch Hạo áp đảo Lâm Thiên trong cuộc đấu sức và bảo thuật, kéo đứt một cánh tay của đối phương rồi trả lại để hắn nối tay. Sau khi Lâm Thiên rút về chiến thuyền tử kim, Thạch Hạo và Ninh Xuyên đối đầu khí thế nhưng hoãn quyết chiến vì các cao thủ vực ngoại vẫn đang hiện diện. Nhóm sứ giả công nhận cả hai là chí tôn một phương, trao cho họ tư cách rời ba ngàn đạo châu để gia nhập Thư viện Thiên Thần. Giữa những lời giới thiệu về Cửu Thiên Thập Địa và hậu duệ Chân Tiên, Đả Thần Thạch cùng mọi người tạo nên một màn trêu chọc xoay quanh Thạch Hạo, Hỏa Linh Nhi và Long Nữ. Thạch Hạo trả Thông Tí thần viên cho Lâm Thiên nhưng giữ chiến xa năm màu, sau đó đưa Hỏa Linh Nhi lên chiến thuyền và cùng Ninh Xuyên tới Trung châu. Tại một đoạn nhai, ba đại nhân vật tiếp đón họ; Thạch Hạo từ chối lời mời bái sư vì đã có sư tôn, nhưng càng quyết tâm đi vực ngoại khi đối phương biết quan hệ giữa hắn và Liễu Thần. Cuối cùng, họ được thông báo phải tìm hiểu Minh ước Thái cổ và tới một tòa cổ thành nguy hiểm trước khi có thể chính thức tiến vào thư viện vô thượng."},{"chuong":1032,"tieuDe":"Con Đường Cửu Tử Nhất Sinh","tomTat":"Ba người đàn ông trung niên tiết lộ đích tuyển chọn nằm tại một tòa cổ thành sâu trong Cấm khu vô ngần ngoài ba ngàn đạo châu, nơi tồn tại bùn vàng, nước kỳ dị và cỏ khô đủ sức giết cả cường giả hàng đầu. Trước sự phản đối của Ninh Xuyên và Thạch Hạo, họ giải thích rằng thư viện Thiên Thần cần tìm một biến số có thể xoay chuyển đại kiếp tương lai chứ không chỉ thu nhận những thiên tài thông thường. Thạch Hạo chấp nhận đi theo con đường cổ xuyên qua Cấm khu vì muốn tự tìm lời giải về Liễu Thần, Biên Hoang và Minh ước Thái cổ. Ba vị trung niên đồng thời mở rộng điều kiện dự tuyển, cho phép mọi cao thủ trẻ tuổi tới được tòa thành đều có tư cách vào thư viện Thiên Thần. Khi rời đoạn nhai, Ninh Xuyên và Thạch Hạo được hai nhóm hộ tống đưa đi riêng để tránh ân oán giữa họ bùng phát thành tử chiến, còn hai cô gái đi cùng Thạch Hạo liên tục khiêu khích hắn nhưng bị cấm động thủ. Hỏa Linh Nhi đau lòng vì không thể theo Thạch Hạo trên con đường cửu tử nhất sinh và hỏi hắn sẽ chuẩn bị gì trước chuyến đi. Thạch Hạo bất ngờ trả lời rằng hắn muốn thành hôn."},{"chuong":1033,"tieuDe":"Thành Hôn Thượng","tomTat":"Trước lúc chia xa, Thạch Hạo đùa về chuyện thành hôn khiến Hỏa Linh Nhi vừa ngượng ngùng vừa buồn vì không biết bao giờ hai người mới gặp lại. Hắn đưa nàng tới Ma châu ra mắt Đại ma thần và công khai gọi nàng là vợ, khiến tổ phụ vui vẻ mở tiệc rồi đề nghị lập tức chủ trì hôn lễ. Thạch Hạo từ chối vì chuyến đi sâu vào Cấm khu có thể khiến mình không trở về, nên không muốn làm lỡ dở Hỏa Linh Nhi. Trước dự cảm thiên hạ sắp đại loạn, hắn hứa dù đang ở đâu cũng sẽ quay lại bảo vệ nàng. Hỏa Linh Nhi muốn đồng hành vào khu vực không người nhưng bị từ chối, còn Sói con được giao nhiệm vụ bảo vệ nàng. Cuối cùng, nàng chọn trở lại Hỏa Tang lâm và hứa sẽ chờ Thạch Hạo năm này qua năm khác, khiến hắn xúc động và cay mắt."},{"chuong":1034,"tieuDe":"Thành Hôn (Hạ)","tomTat":"Hỏa Linh Nhi nén đau từ chối đi cùng Thạch Hạo vì không muốn trở thành gánh nặng, rồi ở lại Hỏa Tang lâm chờ hắn trở về. Sau khi rời đi, Thạch Hạo dùng Thiên Nhãn thông nhìn thấy nàng khóc một mình và được Hỏa Hoàng khuyên phải đối diện với mối duyên chưa trọn. Hắn lập tức quay lại, còn Hỏa Hoàng chủ trì một hôn lễ giản dị để hai người chính thức trở thành phu thê. Trước nỗi lo biến cố có thể khiến họ vĩnh viễn chia lìa, Thạch Hạo thề sẽ tìm lại tất cả dù phải tự tạo ra luân hồi, khiến thiên lôi giáng xuống nhưng bị hắn đánh tan. Đêm tân hôn, hai người chỉ tựa vào nhau dưới trời sao và trò chuyện tới bình minh. Khi Hỏa Linh Nhi bình tâm tiễn bước, Thạch Hạo cáo biệt hai cha con, rời Tội châu và hóa thành Côn Bằng bay về cuối chân trời."},{"chuong":1035,"tieuDe":"Xông Cấm Khu","tomTat":"Thạch Hạo hóa thành Côn Bằng vượt qua nhiều châu để tới biên giới Thặng châu, nơi thư viện Thiên Thần mở rộng kỳ tuyển chọn cho tất cả những ai có thể tìm được cổ thành trong Cấm khu. Bất chấp những cảnh báo về tỷ lệ tử vong và cái chết của lão Giáo chủ thư viện Tạo Hóa, hơn mười vạn người vẫn hội tụ, trong đó có Ninh Xuyên, Trích tiên, Thập Quan vương, Tào Vũ Sinh cùng nhiều thiên tài quen thuộc. Thạch Hạo được nghỉ trên một bồ đoàn lấy từ động phủ tiên gia và nhanh chóng tiến vào trạng thái không linh gần với ngộ đạo. Khi một vị chí tôn thừa nhận chưa từng đi qua con đường cổ, hơn một vạn người rút lui, còn những người ở lại được ba vị chí tôn hợp lực đưa vào Cấm khu rồi phân tán trên tuyến đường rộng tám ngàn dặm. Đi một mình trong khu rừng im lặng, Thạch Hạo phát hiện hơn mười tu sĩ đã bị hút sạch máu thịt và xương tủy, chỉ còn những lớp da khô treo trên cây. Một vật giống cỏ khô bất ngờ tập kích và nghiền nát cả ngọn núi sau khi đâm hụt, khiến hắn rút tiên kiếm Đại La chuẩn bị chiến đấu. Qua cổ ngữ và thần niệm, Thạch Hạo nhận ra một sinh linh từ bên kia Biên hoang đã xâm nhập nơi này và đang coi đoàn người dự tuyển là thức ăn."},{"chuong":1036,"tieuDe":"Sinh Linh Bên Kia Biên Hoang","tomTat":"Trong khu rừng cổ thuộc vùng không người, một sinh linh vô hình hút sạch huyết nhục của tu sĩ ba ngàn đạo châu, chỉ để lại lớp da khô. Thạch Hạo dùng Thiên Nhãn thông và pháp môn Côn Bằng buộc đối phương hiện nguyên hình là một Tròng mắt đen khổng lồ có thể ẩn trong hư không. Tròng mắt triệu hồi huyết trì ăn mòn, còn Thạch Hạo dùng lôi trì dung hợp nhiều loại lôi điện đối kháng nhưng vẫn bị thương nặng. Trong lúc giao chiến, Tròng mắt tuyên bố Biên hoang sắp bị phá và phe bên kia đã chuyển sang phương án hai nhằm khiến ba ngàn đạo châu không còn tồn tại. Nó cũng khiến Thạch Hạo lo ngại rằng thất đại vương giả từng trấn thủ Biên hoang có thể đã gặp bất trắc. Đoạn chiến mâu đồng gỉ sét cắm trong Tròng mắt sau đó thức tỉnh, để lộ mình là tàn binh của Tiên khí vỡ nát và vẫn mang ý chí Tiên đạo. Thạch Hạo tận dụng thời cơ tiếp tục công kích, phối hợp với sức mạnh của chiến mâu để chấn Tròng mắt thành hai nửa."},{"chuong":1037,"tieuDe":"Tiên Đồ","tomTat":"Thạch Hạo giao chiến với Tròng mắt đã hóa thành hố đen và mở cánh cửa nối với con đường màu máu. Khi hắn vung kiếm thai Đại La, đoạn mâu đồng gãy cắm trong đối thủ cộng hưởng với kiếm, tự phân hủy và kéo Tròng mắt vào hủy diệt; tàn linh còn lại cũng lập tức hóa tro. Nhận thấy kiếm thai có lai lịch khác thường và Biên hoang đang bất ổn, Thạch Hạo quyết tiếp tục hành trình, đồng thời mau chóng tăng tu vi trước khi đại kiếp kéo tới. Trong Cấm khu, hắn vượt qua tàn trận được bố trí từ hàng vạn đại tinh màu lam, nơi kiếm khí vô hình chuyên chém nguyên hồn, rồi phát hiện Thanh Tiên đang bị giam cầm. Thanh Tiên niết bàn thành hạt giống xanh biếc và nhờ hắn chôn mình gần nơi lưu lại khí tức Hỗn Độn Thanh Liên để biến đại kiếp thành cơ duyên. Năm ngày sau, Thạch Hạo đi qua Tử Trúc lâm và bước vào một thế giới tràn ngập tiên vụ, linh sơn, cổ dược cùng những sinh linh tưởng như chỉ còn tồn tại trong truyền thuyết. Gặp các cư dân Tiên phủ không hề biết ba ngàn đạo châu, hắn ngỡ ngàng tự hỏi mình đang mộng về Tiên cổ hay Tiên cổ đã thực sự tái hiện."},{"chuong":1038,"tieuDe":"Nam Hải Tử Trúc Lâm","tomTat":"Thạch Hạo choáng váng trước những sinh linh và tu sĩ mang khí chất Tiên đạo, buộc phải giả vờ chóng mặt rồi dùng chuyện dung hợp cổ hỏa để che giấu sự khác biệt trong con đường tu luyện. Kiếm thai Đại La của hắn khiến những người trẻ tuổi cảm thấy quen thuộc, dù họ tạm cho rằng nó chỉ là hàng mô phỏng, từ đó làm hắn nghi ngờ lai lịch thật của thanh kiếm. Mong tìm hiểu hệ thống tu hành xa lạ, Thạch Hạo theo đoàn người vượt biển xanh và xuyên qua rừng trúc tím để dự thịnh hội tại đạo thổ giữa Nam Hải. Trên đường, hắn chứng kiến Chân Tiên cưỡi rắn tám đầu, Bạch Giao quân vương rẽ biển và đại chuông của Vô Chung vượt trời tới hội. Khung cảnh động phủ thanh bình, đầy tiên khí với thần lộc dâng quả và vượn trắng rót rượu khiến hắn nảy sinh ý muốn ở lại mãi nơi này. Sau đó, Lục Đạo Luân Hồi Tiên vương bước trên con đường tử kim tiến vào đảo và được mọi người đứng dậy nghênh đón. Thạch Hạo chấn động khi nhận ra nhiều mảnh Luân Hồi bàn đang lơ lửng trên đỉnh đầu vị Tiên vương, cùng loại với mảnh nhỏ hắn từng thấy ở hạ giới."},{"chuong":1039,"tieuDe":"Về Tiên Cổ","tomTat":"Thạch Hạo biết Lục Đạo Luân Hồi Tiên vương là người luyện chế Luân Hồi bàn, đồng thời chí bảo này đã bị chính ông phá hủy thành nhiều phần. Một đại nhân vật hóa thân từ Kim Ô tới Nam Hải Tử Trúc lâm và dùng một chỉ tạo ra thái dương mới, khiến Thạch Hạo kinh hãi trước thần thông tuyệt thế. Khi nghe các thiên kiêu luận đạo và trực tiếp giao thủ với thiếu nữ ôm Kỳ lân con, Thạch Hạo nhận ra hệ thống Tiên cổ dung hợp Tiên chủng để trực tiếp nắm giữ đại đạo, khác với con đường thường khởi đầu từ bảo thuật của thời mình. Hắn tiếp tục luận bàn với Hoàng nữ và chàng trai mang bảo kiếm tiên kim Quang Minh, để lộ ba luồng tiên khí và biết Hoàng nữ từng luyện hóa một mô hình vũ trụ làm Tiên chủng. Thạch Hạo lưu lại Tử Trúc lâm nửa năm, kết giao với nhiều thiên kiêu trong lúc các đại nhân vật nghiên cứu Thời gian và Luân hồi. Tin tức truyền tới cho biết Vô Chung nhận ra chữ Chung chưa thể khiến con đường viên mãn mà còn cần thêm chữ Thủy, còn Lục Đạo Luân Hồi Tiên vương vẫn suy tính khả năng tồn tại của luân hồi nhân thế. Cuối cùng, những người bạn Tiên cổ buồn bã báo rằng đây có thể là lần gặp cuối kéo dài vô tận năm tháng, khiến Thạch Hạo gặng hỏi chân tướng nhưng chưa nhận được câu trả lời."},{"chuong":1040,"tieuDe":"Mộng Về Đời Kia","tomTat":"Sau vài tháng sống cùng các chí tôn trẻ tuổi trong Tiên phủ, Thạch Hạo linh cảm cuộc hội ngộ sắp kết thúc bằng một lần vĩnh biệt. Kẻ thù từ ngoài vũ trụ nhanh chóng tràn vào bằng những lực lượng quỷ dị như con mắt đỏ, sương xám, vảy máu và dây leo, lần lượt sát hại những người Tiên cổ dù họ dốc sức chống trả. Thạch Hạo điên cuồng xuất thủ cứu giúp nhưng hoàn toàn không thể tác động đến chiến trường vì bản thân chỉ là một nhân chứng bị kéo vào kỳ cảnh xuyên thời gian. Thiếu nữ ôm Kỳ lân và Hoàng nữ cho hắn biết cảnh tượng này được các đại nhân vật lưu lại để người đời sau hiểu sự tàn khốc của Tiên cổ và chuẩn bị nghênh chiến cùng một kẻ thù trong tương lai. Lục Đạo Luân Hồi Tiên vương cùng Vô Chung vừa đối đầu cường địch vừa dùng đạo hạnh xuyên qua chư thiên, chiếu lại quá khứ và kéo người đương đại tới chứng kiến, nhưng Luân Hồi bàn đã nứt còn chuông lớn cũng bị tổn hại. Hoàng nữ tiết lộ ngoài Thạch Hạo còn có vài người khác được tìm kiếm như những niềm hy vọng có thể mộng về thời đại này. Chứng kiến những người bạn Tiên cổ lần lượt chết trong máu, Thạch Hạo đau đớn từ biệt họ và nảy sinh khát vọng một ngày đủ mạnh để tác động thời gian, tạo nên luân hồi và gặp lại những người đã mất."},{"chuong":1041,"tieuDe":"Cấm Khu Nguy Hiểm","tomTat":"Thạch Hạo tỉnh lại tại di tích Nam Hải Tử Trúc lâm và tìm thấy mảnh bảo kiếm tiên kim Quang Minh cùng Hoàng cốt năm màu, qua đó xác nhận trải nghiệm về kỷ nguyên Tiên cổ không phải ảo mộng. Hắn mai táng hai di vật, tưởng niệm những bằng hữu đã chết và lập chí trở nên mạnh mẽ để một ngày kia đối đầu những kẻ đã hủy diệt họ. Trên đường xuyên qua Cấm khu, hắn lần lượt tránh được tấm da thú phóng thần châm vàng, dãy mộ cổ rỉ máu và thần mộc chứa lôi điện đủ sức giết Giáo chủ. Sự dịch chuyển của các ngôi mộ còn làm lộ hàng ngàn thi thể thiên tài trẻ tuổi đến từ ba ngàn châu. Hai tháng sau, một đoàn cao thủ mặc thiết y tự nhận đến từ tòa thành cổ bất ngờ dùng bí bảo phục kích Thạch Hạo, nhưng bị hắn phản kích và giết nhiều người. Ngay sau tín hiệu cầu viện của họ, một đội áo đen toàn cấp Thiên Thần cưỡi cổ thú màu máu kéo tới và ra lệnh truy sát hắn."},{"chuong":1042,"tieuDe":"Kẻ Địch","tomTat":"Thạch Hạo bị một toán Thiên Thần thiện chiến cưỡi hung thú vây công tại nơi sâu Cấm khu. Hắn dùng Bảo thuật Liễu Thần chia cắt chiến trường, sau đó vận chuyển phù văn Luân hồi qua kiếm thai Đại La để làm thủ lĩnh đối phương già yếu rồi chém chết cả thân thể lẫn nguyên thần. Những kẻ còn lại định dùng đá nhiều màu bố trí trận pháp, nhưng Thạch Hạo triển khai cánh Côn Bằng, nhiều bảo thuật và sáu bảy linh thân để truy sát, không cho bất kỳ ai trốn thoát. Đôi mắt đỏ như máu của nhóm phục kích giống những con mắt phủ sương trong giấc mộng Tiên cổ, còn một tù binh đã tự hủy nguyên thần để ngăn việc dò xét. Từ những dấu hiệu này, Thạch Hạo nghi Biên hoang đã bị công phá và đại quân địch đã vượt ải. Dù lo mình có thể bị giết khi chưa trưởng thành tới đỉnh cao, hắn vẫn quyết định không rút lui mà tiếp tục tiến sâu. Vài ngày sau, Thạch Hạo nhìn thấy một tòa thành lớn và hùng vĩ ở cuối chân trời."},{"chuong":1043,"tieuDe":"Một Tòa Thành!","tomTat":"Thạch Hạo vượt qua bình nguyên khô cằn và tìm thấy một thành trì nguy nga gần Biên hoang, nhưng nơi này chưa phải cổ thành biên giới chân chính. Trong thành, hắn gặp lại Ma nữ và biết nàng tới trước nhờ một truyền tống trận, còn viên thạch châu của nàng có thể cảm ứng với tàn tháp hắn từng mang. Ma nữ giải thích thành trì được hình thành từ đệ tử và hậu duệ của các cao thủ từng thực hiện Minh ước Thái cổ, đồng thời cảnh báo khí thế từ Biên hoang đang ăn mòn tâm trí một số cao thủ. Từ vụ Thạch Hạo từng bị phục kích, hai người nhận định Biên hoang có thể sắp đại loạn và kẻ địch đang chuẩn bị phá ải. Nghe tin quanh thành có cơ duyên được đồn là trứng Kỳ lân thuần huyết, Thạch Hạo quyết định lưu lại tìm kiếm. Hai ngày sau, dị tượng Kỳ lân trắng xuất hiện và sinh linh trong đó trực tiếp đối thoại với hắn. Khi Thạch Hạo nhắc tới Nam Hải Tử Trúc lâm cùng cô bé từng ôm nó, Kỳ lân nhận ra hắn là người trong ký ức Tiên cổ rồi bật khóc vì đã chờ cô bé ấy suốt vô tận năm tháng mà nàng không bao giờ trở lại."},{"chuong":1044,"tieuDe":"Ma Hóa","tomTat":"Thạch Hạo bất ngờ liên lạc được với Kỳ lân con từng xuất hiện trong chuyến thần du về cuối thời Tiên cổ, qua đó xác nhận thảm kịch tại Nam Hải Tử Trúc lâm là sự thật. Kỳ lân con kể rằng nó từng được truyền tống khỏi hiểm cảnh, mai táng trong vật chất bất tử và ngủ say suốt vạn cổ, nhưng vẫn nhất quyết chờ cô bé chủ nhân trở về. Nó dùng một chí bảo Tiên cổ để che giấu chân thân rồi biến mất, còn Thạch Hạo trở lại thành cổ và thuyết phục Ma nữ từ bỏ việc tìm Kỳ lân để tiếp tục tới Biên hoang tìm Đế thành. Trên đường đi, hai người bị một đội hơn mười Thiên Thần mắt đỏ truy đuổi; đội trưởng xác nhận Thạch Hạo đã giết Đội Mười Chín nhưng thừa nhận lực lượng hiện tại không đủ sức đối đầu. Các Thiên Thần này vốn là tu sĩ ba ngàn châu đã bị ma hóa, sau đó dùng máu huyết bản thân hiến tế lên một tế đàn ẩn trong núi đá. Ma nữ nhận ra nghi thức có thể gọi sinh linh từ bên kia Biên hoang giáng lâm. Cuối chương, một giọng nói trẻ tuổi nhưng đầy uy thế vang lên từ tế đàn và hỏi những kẻ triệu gọi có muốn bản thể của hắn hiện ra hay không."},{"chuong":1045,"tieuDe":"Huyết Tế Đàn","tomTat":"Một ngọn núi đá nứt ra, để lộ Huyết Tế Đàn được nhóm Thiên Thần ma hóa phụng làm chủ, và Thạch Hạo nhận ra nó là con đường nối sang phía bên kia Biên hoang. Thạch Hạo cùng Ma nữ tiêu diệt toàn bộ nhóm Thiên Thần, đồng thời giam cầm huyết dịch để ngăn tế đàn tiếp tục hấp thu vật hiến tế. Lạc Mộ xuất hiện qua tế đàn, tự nhận là cường giả đầu tiên sau vạn cổ quân lâm vùng đất này, nhưng vì con đường chưa hoàn thiện nên chỉ có thể đưa hóa thân tinh khí thần vượt qua. Hắn vận chuyển hai Tiên chủng âm dương, diễn hóa một vũ trụ nhỏ để trấn áp Thạch Hạo, song vẫn bị đối phương phá giải và đánh nổ mi tâm hóa thân. Khi chân thân Lạc Mộ cố vượt giới lần nữa, Ma nữ dùng thạch châu đánh nát Huyết Tế Đàn, khiến hắn bị đẩy trở lại và con đường xâm nhập bị cắt đứt. Xử lý xong mối họa, Thạch Hạo và Ma nữ tiếp tục lên đường tiến về thành Thiên đế."},{"chuong":1046,"tieuDe":"Đế Cốt Dưới Vùng Biển","tomTat":"Thạch Hạo và Ma nữ tiếp tục tiến về Đế thành ở cuối Cấm khu nhưng bị vùng biển cổ chiến trường chắn đường. Dấu ấn kèn lệnh ốc biển tái hiện cảnh trời đất nổ tung từ cuộc chiến hơn một kỷ nguyên trước, sau đó kiếm khí thật sự bùng phát cắt đứt thiên địa và kéo thiên thạch rơi xuống. Hai người mất hơn nửa tháng đi vòng qua vùng biển, hỏi đường tại cổ thành và xác nhận ba vị đại chí tôn có thể đã tới Đế thành trước bằng truyền tống trận. Tiến vào biển dung nham theo lời ghi trên bia đá gãy, Thạch Hạo định bắt một con Dương ngư cấp Thiên Thần giàu vật chất thần tính nhưng con cá thu nhỏ trốn thoát qua trận pháp dưới đáy. Một khung xương trắng sức mạnh vượt Thiên Thần vươn móng vuốt tấn công, Ma nữ dùng Trấn Hồn châu chặn đứng và khiến bộ xương chìm trở lại biển dung nham. Mỏm đá khắc chữ xác nhận nơi đây là Vùng biển Đế cốt, mai táng các nhân vật cái thế được gọi là Đế. Thiên nhãn của Thạch Hạo nhìn thấy nhiều bộ hài cốt dưới đáy, một bộ xương ngồi xếp bằng sáng như mặt trời phóng tinh lực còn sót xuyên trời đánh rơi sao trời. Ma nữ kết luận tất cả Đại Đế nơi đây đều chết trận, phản ánh mức tàn khốc của đại chiến năm xưa."},{"chuong":1047,"tieuDe":"Phượng Hoàng Sơn","tomTat":"Thạch Hạo và Ma nữ vượt qua biển dung nham, chứng kiến nhiều bộ Đế cốt cùng những tàn binh có uy thế đáng sợ nhưng không dám thu lấy. Thạch Hạo dự đoán nơi đây có thể trở thành chiến trường khi kẻ địch của các cường giả đã chết tìm tới. Sau khi đi thêm trăm vạn dặm, hai người phát hiện Phượng Hoàng Sơn cùng một cổ thành đầy cây ngô đồng chết khô trên đỉnh. Trong lúc định rút lui, họ vô tình khơi dậy đại trận và bị nhốt trong thành, nơi một quái vật một chân dùng đại bổng Lang Nha tàn phá các kiến trúc rồi đột ngột biến mất. Tiếp đó, họ gặp một ông lão xác ướp vẫn hành động bằng chấp niệm, có thể hái hai ngôi sao và luyện thành hạt châu. Sau khoảng một tháng rưỡi thăm dò, hai người kích hoạt đại trận truyền tống tới một động phủ tràn ngập hỗn độn khí và tiên quang. Tại đây, họ tìm thấy một quả trứng tỏa sinh cơ mạnh mẽ và nghi nó thuộc về Phượng Hoàng, dù nguồn gốc thật sự vẫn chưa được xác nhận."},{"chuong":1048,"tieuDe":"Trứng Tiên","tomTat":"Trong động phủ Tiên cổ, Thạch Hạo phát hiện một quả trứng năm màu mang khí tức của Hoàng nữ, người bạn hắn từng gặp khi thần du về thời Tiên cổ. Võ đạo Thiên nhãn cho thấy quả trứng chứa tinh khí sinh mệnh hùng hậu nhưng không còn dấu vết linh hồn, khiến Ma nữ suy đoán đây là kết quả của một lần niết bàn thất bại. Thạch Hạo vẫn không cho phá hủy quả trứng, còn Ma nữ nhường nó cho hắn và đề nghị tìm một cường giả thuộc tính Hỏa cùng tu luyện, khiến hắn nghĩ tới Hỏa Linh Nhi. Hai người rời động phủ, mất nửa tháng vượt biển dung nham đầy hiểm họa rồi tiếp tục đi suốt ba tháng về phía sâu trong Cấm khu. Khi Đế thành Cấm khu hiện ra với khí thế kỳ dị, giọt máu thần bí trên người Thạch Hạo bắt đầu thức tỉnh và chiếu rọi chư thiên vạn cổ. Ma nữ nhận ra đó là giọt máu từng được mang ra từ di địa Tiên cổ và chôn sâu dưới Vạn Vật thổ."},{"chuong":1049,"tieuDe":"Đế Thành Cấm Khu","tomTat":"Khi Thạch Hạo và Ma nữ tiến gần tòa thành nơi chân trời, giọt Đế huyết bỗng cộng hưởng, phát sáng và tái hiện cảnh đại chiến kinh khủng giữa chư thiên. Hai người tận mắt thấy Đế thành khổng lồ được luyện từ các ngôi sao, có đại tinh vận chuyển xung quanh và được trận pháp vô thượng bao phủ. Dựa vào ký ức từ chiếc thuyền đen nhuốm máu, Thạch Hạo xác định nơi này không phải thành cổ do bảy vị Vương cùng nhóm người mang tội huyết tử thủ, qua đó nhận ra Biên hoang còn nhiều tầng chiến tuyến chưa sáng tỏ. Bia đá ngoài thành cho biết chỉ người đã ký Minh ước Thái cổ mới được vào, còn người cưỡng ép vượt qua sẽ hình thần đều diệt; Ma nữ cũng phải dùng thạch châu chống lại áp lực cấm chế. Không nhận được hồi đáp hay phát hiện sinh linh trong Đế thành, hai người đi vòng quanh và tìm thấy khu phố chợ do hậu duệ các cao thủ tuyệt đại phát triển. Tại tòa thành lớn nhất trong khu vực, họ gặp lại Thập Quan vương, Trích tiên, Ninh Xuyên, Nguyệt Thiền cùng số ít tu sĩ sống sót sau hành trình. Một nhóm tu sĩ Cửu Thiên tách thành phe riêng, công khai đánh giá thiên tài của mình cao hơn người ba ngàn châu, trong khi Nguyệt Thiền nhìn thấy Thạch Hạo đang đi cùng Ma nữ."},{"chuong":1050,"tieuDe":"Đối Nghịch","tomTat":"Trước cổ thành, các thiên tài đến từ ba ngàn đạo châu và Vô Lượng Thiên chia thành nhiều nhóm, ngầm hình thành các liên minh. Nhóm Vô Lượng Thiên mời Ma nữ tới thánh thổ tu luyện nhưng tỏ thái độ khinh thị Thạch Hạo vì những lời nói ngông cuồng từng được truyền lại. Thạch Hạo quyết định dùng chàng trai tóc vàng làm mục tiêu lập uy, khiến đối phương xuất chưởng và làm hư không nổ tung trước khi cuộc giao đấu bị cao thủ trong thành ngăn cản. Thạch Hạo phất tay khép lại hư không, còn một ông lão áo tím cấp Giáo chủ xuất hiện với nhiệm vụ thống kê người tới nơi này và buộc hai bên tạm dừng xung đột. Trích tiên sau đó dùng Thiên nhãn nhận ra Ma nữ từng đạt một phần truyền thừa liên quan tới mình, gọi nàng là sư muội và được nàng sang đứng cạnh. Thạch Hạo lần lượt gặp lại Cát Tiềm, Trường Cung Diễn, Long Nữ và Tào Vũ Sinh. Cuối cùng, một vị chí tôn trung niên xuất hiện giữa hư không và tuyên bố đã đến lúc xác định danh sách người được tiến vào thư viện Thiên Thần."},{"chuong":1051,"tieuDe":"Thử Thách","tomTat":"Một vị Chí Tôn trung niên công bố quy tắc tuyển chọn của Thiên Thần thư viện, xác nhận người ba ngàn đạo châu đạt điều kiện đều có thể thông qua và giao nhiệm vụ tìm diệt những kẻ đã bị bóng tối ăn mòn. Tiếng kèn từ phía bên kia Đế Thành khiến ông lo bi kịch Tiên cổ tái diễn, đồng thời cảnh báo lớp thiên tài mới không được phản bội đồng loại để cầu sống. Thạch Hạo bí mật báo về lời cảnh báo của nhãn cầu ngủ say vạn năm và tế đàn nối liền hai giới mà hắn từng phá hủy, nhưng được yêu cầu giữ kín chuyện này. Khi quy tắc lập đội tối đa năm người được ban bố, Tào Vũ Sinh, Trường Cung Diễn và Long Nữ đứng cùng Thạch Hạo, còn Ma nữ chọn đi với Trích Tiên. Thạch Hạo tiếp tục trêu Cát Tiềm và Nguyệt Thiền, khiến Cát Tiềm tức giận bỏ đi còn Nguyệt Thiền mất vẻ điềm tĩnh. Hai vị Chí Tôn còn lại sau đó công bố Bạch Kỳ Lân ấu thú gần một tòa cổ thành là mục tiêu đặc biệt, với phần thưởng được Thiên Thần thư viện dốc sức bồi dưỡng. Sau khi các thiên tài tản đi, ba vị Chí Tôn tiết lộ họ cũng không thể tìm thấy ấu thú vì nó mang Tiên bảo và nghi đây là bố trí do Luân Hồi Tiên vương lưu lại để chờ một thiếu nữ, qua đó nghiệm chứng Luân Hồi."},{"chuong":1052,"tieuDe":"Kỳ Lân Hiện","tomTat":"Đoàn Thạch Hạo dùng Truyền Tống trận trở lại thành trì từng xuất hiện tung tích Bạch Kỳ Lân, nơi hình chiếu của ấu thú gần đây biểu lộ niềm vui khác thường. Trong lúc các thiên tài tụ hội, một chàng trai tóc vàng đến từ Vô Lượng Thiên công khai đe dọa Thạch Hạo, nhưng hai bên chưa giao chiến vì còn chịu sự đánh giá của ba đại cường giả. Cô Kiếm Vân cho rằng Ninh Xuyên mới là người hữu duyên với Kỳ Lân, bởi hắn có Kỳ Lân văn bẩm sinh và sinh ra tại nơi lưu truyền chuyện Bạch Kỳ Lân ẩn náu. Sau khi Ninh Xuyên cảm ứng được Kỳ Lân sắp xuất thế, Trích Tiên, Thập Quan vương, Thạch Hạo và nhiều thiên tài khác lập tức truy theo hắn vào Nguyên thủy Đại Hoang. Đoàn người gặp anh linh mạnh hơn giáo chủ, một thi hài nghi thuộc Chí Tôn và khu rừng đầy vũng máu cổ, nơi một thiên tài đã tu thành tiên khí bị kéo xuống rồi hòa tan tức khắc. Ninh Xuyên thúc giục Kỳ Lân văn cộng hưởng với núi sông, khiến hỗn độn khí và tiên hà dâng lên, đồng thời làm một ngọn núi nứt mở. Bạch Kỳ Lân chân chính lao ra bên cạnh một thiếu nữ mang Tiên Đạo khí tức. Thạch Hạo mở Thiên mục quan sát, nhận ra thiếu nữ và kinh hãi nghi ngờ nàng đã Luân Hồi từ thời Tiên cổ."},{"chuong":1053,"tieuDe":"Tranh Cướp","tomTat":"Ngọn núi phong ấn sụp đổ, Thái Âm Ngọc Thỏ xuất hiện cùng một Bạch Kỳ Lân non và lập tức trở thành mục tiêu tranh đoạt của quần hùng. Ninh Xuyên cùng các tu sĩ vực ngoại chặn đường nàng, trong khi Trích Tiên, Ma nữ, Thập Quan vương, Nguyệt Thiền, Thạch Nghị và nhiều chí tôn trẻ tuổi khác lần lượt hiện thân. Một Thiên Lang màu xanh lao tới bắt Kỳ Lân, nhưng Ninh Xuyên phá binh khí của kẻ trợ chiến rồi dùng Kỳ Lân thuật tiêu diệt Thiên Lang chỉ trong một quyền. Khí tức của bảo thuật đồng tộc khiến Bạch Kỳ Lân chú ý đến Ninh Xuyên, song khi hắn và chàng trai tóc vàng cùng cưỡng ép tranh bắt, con non vẫn tránh họ và nhảy vào lòng Thái Âm Ngọc Thỏ. Thạch Hạo kịp thời chắn trước thiếu nữ, đồng thời dùng Luân Hồi quyền và Liễu Thần pháp nghênh chiến hai cường địch. Sau cuộc va chạm làm không gian và núi sông tan vỡ, Thạch Hạo vẫn đứng nguyên tại chỗ, khiến hai đối thủ hiểu rằng muốn vượt qua hắn sẽ phải trải qua một trận chiến liều mạng."},{"chuong":1054,"tieuDe":"Trấn Áp Vực Ngoại Địch","tomTat":"Nhiều phe tập trung tranh đoạt Bạch Kỳ Lân: chàng trai tóc vàng muốn đem nó về Vô Lượng Thiên cho cổ tổ, Ninh Xuyên tuyên bố có duyên với nó, còn Thạch Hạo cùng đồng bạn đứng ra bảo vệ. Trong lúc căng thẳng, Tiểu Bạch để lộ linh trí khi đáp trả lời trêu chọc của Tào Vũ Sinh, nhưng không giải thích quan hệ mơ hồ giữa mình, Thái Âm Ngọc Thỏ và Ninh Xuyên. Chàng trai tóc vàng ra tay trước bằng hoàng kim trường thương, song Kiếm thai Đại La chém nứt binh khí, hút hết tinh hoa Hoàng Đạo Tiên Kim và làm đồ án phi tiên xuất hiện thêm lôi kiếp màu vàng. Thạch Hạo sau đó cất kiếm, vận dụng Bảo thuật Lôi Đế và Pháp môn Côn Bằng để một mình đánh trọng thương nhiều tu sĩ vực ngoại, nhưng chủ động không diệt nguyên thần vì dè chừng thái độ của Tam đại Chí Cường giả đối với nội chiến. Chàng trai tóc vàng thi triển bí pháp huyết mạch để hóa thành hoàng kim thân thể vẫn bị Thạch Hạo đánh thủng lưng và đánh bay. Nhân lúc hỗn chiến, Ninh Xuyên lao tới đoạt Tiểu Bạch nhưng bị Thạch Hạo quay lại ngăn cản, buộc hai người trực tiếp đối đầu. Trước cả tu sĩ ba ngàn châu lẫn vực ngoại, Thạch Hạo công khai nhắc lại việc từng đánh Ninh Xuyên bỏ chạy tại Tiên cổ di địa."},{"chuong":1055,"tieuDe":"Ứng Cử Viên","tomTat":"Thạch Hạo và Ninh Xuyên, hai bá chủ trẻ tuổi cùng nắm giữ ba luồng tiên khí, tiếp tục cuộc quyết đấu dang dở vì Ninh Xuyên muốn rửa nhục lần độ kiếp bị quấy nhiễu. Một trong tam đại trung niên Chí Tôn dùng một chỉ cầm cố hư không, tách hai người để tránh thiên tài tự hao tổn trước chiến loạn sắp tới. Thạch Hạo nhân đó truy hỏi căn nguyên danh xưng Tội Huyết hậu nhân, nhưng chỉ biết chuyện năm xưa liên quan nhiều thế lực và vẫn còn nhân chứng sống. Sau khi nhiệm vụ truy tìm sinh linh ma hóa cùng Kỳ Lân con non được xác nhận hoàn thành, các Chí Tôn đưa toàn bộ thiên tài trở lại khu vực Đế Thành, nơi chỉ Đế giả hoặc người ký Thái cổ Minh Ước mới được tiến vào. Tại thành trì ngoài Đế Thành, Thạch Hạo gặp lại Chân Cổ, Đằng Nhất, Phượng Vũ, Tả Tiểu Địch, Mục Tử Tiêu và nhiều ứng cử viên khác, còn Thái Âm Ngọc Thỏ cùng Kỳ Lân con non được các Chí Tôn mang đi. Thạch Hạo sau đó gặp Thanh Y, nhắc lại lời hẹn lấy thân báo đáp tại Tiên cổ rồi giữ tay và ôm eo nàng. Vì quan hệ chủ thân và thứ thân, Nguyệt Thiền trực tiếp cảm nhận cảm xúc của Thanh Y, lên tiếng ngăn cản và lo rằng việc cùng hai người tiến vào Thiên Thần thư viện sẽ trở thành sự giày vò lâu dài."},{"chuong":1056,"tieuDe":"Vào Thành","tomTat":"Nguyệt Thiền hoảng sợ trước viễn cảnh phải cùng Thanh Y và Thạch Hạo vào Thiên Thần thư viện, trong khi Thạch Hạo và Tào Vũ Sinh tiếp tục trêu chọc quan hệ chủ–thứ thân của hai nàng. Các thiên tài ba ngàn châu hội tụ thành nhiều nhóm, còn Tần Hạo bất ngờ xuất hiện và lựa chọn cùng anh trai rời đi, khiến Thạch Hạo day dứt vì cha mẹ sẽ không còn người con nào ở bên. Theo đề nghị của Thái Âm Ngọc Thỏ, tam đại Chí Cường giả cho toàn bộ tu sĩ ba ngàn châu đã tới nơi vượt qua khảo nghiệm. Họ hợp ba mảnh tàn cốt thành tiểu tế đàn, thu mọi người rồi truyền tống vào một chiến trường cổ tối tăm, cháy khét và phủ đầy xương khô bên trong Đế Thành. Đoàn thiên tài được lệnh tự tìm các bia đá ghi Thái cổ Minh Ước, đồng thời phải tránh những khe lớn có thể dẫn thẳng ra ngoài biên quan và tới thế giới của kẻ địch. Dù tam đại Chí Cường giả luôn giám sát bằng thần thức, Thạch Hạo vẫn bất ngờ bước lên một lối đi màu đen và biến mất khỏi đoàn. Hắn được đưa tới một vùng đất tối tăm khác, nơi chân thân chiếc đỉnh ba chân hai tai nhuốm máu đang lưu chuyển mẫu khí và tỏa ra khí tức kinh người. Trước cảnh tượng ấy, Thạch Hạo liên tưởng tới bí mật biên hoang và tự hỏi bên trong chiếc đỉnh rốt cuộc cất giấu điều gì."},{"chuong":1057,"tieuDe":"Đến Từ Tương Lai","tomTat":"Trong chiến trường tối tăm, Thạch Hạo gặp chân thân của chiếc đỉnh ba chân hai tai mà hắn từng chỉ nhìn thấy dưới dạng dấu ấn hư không dưới hắc uyên thuộc di tích Tiên cổ. Tiếng thần niệm phát ra từ những giọt huyết trên đỉnh cho biết mình đã đến sớm và không thuộc về quá khứ hay hiện tại, khiến Thạch Hạo suy đoán đối phương có liên hệ với tương lai. Mỗi lần hai bên trao đổi, vô thượng lôi kiếp cùng quy tắc phản phệ lập tức giáng xuống, buộc bảo đỉnh phải thu nạp lôi đình, luyện hóa kiếp quang và dùng thiên địa mẫu khí chữa lành hư không. Từ lời cầu viện từng nhận được trong lần gặp trước, Thạch Hạo lo ngại kỷ nguyên hiện tại có thể lặp lại kết cục diệt vong của Tiên cổ, nhưng hắn tuyên bố sẽ siêu thoát bất hủ và đánh bại mọi địch thủ cổ kim. Ở bên ngoài, Tam Đại Chí tôn không thể tìm thấy hắn, nhận định sức mạnh can thiệp vượt xa mình rồi triệu tập các thiên tài rời khỏi Đế Thành. Cuối cùng, tiếng thần niệm dốc sức chống lại quy tắc để hẹn gặp Thạch Hạo trong một trận chiến chưa rõ, làm vô tận sấm sét, tiên khí và quy tắc điên cuồng bùng phát."},{"chuong":1058,"tieuDe":"Thế Giới Phía Bên Kia","tomTat":"Cuộc đối thoại xuyên kỷ nguyên giữa Thạch Hạo và cổ đỉnh dẫn tới Tiên Đạo lôi đình, buộc cổ đỉnh phải xông lên chém tan sức mạnh hủy diệt này và chịu phản phệ đến mức trở nên ảm đạm. Thạch Hạo hiểu rằng tương lai không thể bị tiết lộ trực tiếp vì mọi hành động can thiệp vào lịch sử đều có thể khuấy động nhân quả và bị chư thiên vạn giới xóa bỏ. Dù nhớ lại viễn cảnh vạn cổ cô tịch, nơi mọi người kể cả Liễu Thần đều đã chết, hắn vẫn kiên quyết phủ nhận đó là kết cục cuối cùng. Cổ đỉnh sau đó xé hư không rời đi, để lại một khe nứt mà Thạch Hạo lập tức vượt qua vì tin nó đang dẫn đường cho mình. Hắn từ chiến trường cháy đen đầy xương khô tiến vào một vùng tịnh thổ non xanh nước biếc, có linh khí dồi dào nhưng chịu sự chi phối của quy tắc đại đạo khác thường. Tại đây, một Tử Vong Long Chủy Điểu mắt đỏ tập kích hắn bằng thân thể cứng chắc và long hình quang nhận, buộc hắn vận dụng Côn Bằng pháp để trấn áp. Ma cầm nhanh chóng mục nát thành bụi, trong khi những hung thú mắt đỏ khác cũng không thể thuần phục và hóa tro khi bị thương. Từ các dấu hiệu ấy, Thạch Hạo nghi mình đã tới lãnh địa của kẻ địch và quyết định tiếp tục điều tra chân tướng của thế giới phía bên kia."},{"chuong":1059,"tieuDe":"Biên Hoang Sinh Linh","tomTat":"Thạch Hạo rời nơi giáng lâm và thăm dò một thế giới có quy tắc thiên địa khác biệt, khiến hắn nghi mình đã vượt qua biên hoang. Trong vùng núi tím, hắn phát hiện hoàng kim thánh tham cùng nhiều thánh dược Tiên cổ đều cắm rễ trên thi hài cường giả để hấp thu tinh khí. Khi phá núi kiểm chứng, hắn nhận ra cả vùng sơn mạch chôn đầy hài cốt của nhiều chủng tộc từng sống trong thế giới Tiên cổ. Rời núi tới bình nguyên, hắn bắt gặp một chiến xa do tám Ngân Sắc Ngô Công cấp Thiên Thần kéo và nghe tiếng cười của một thiếu nữ bên trong. Tiếp tục khảo sát, hắn tìm thấy hơn mười cổ thành thuộc nhiều chủng tộc, trong đó khoảng một nửa do Nhân tộc hoàn toàn giống mình nắm giữ. Thạch Hạo bắt hai người ngoài thành, đọc thần thức để học cổ ngữ và phong tục rồi thay y phục bản địa trà trộn vào một cự thành Nhân tộc. Tại đây, hắn nghe cư dân tuyên bố Cửu Thiên Thập Địa vốn là linh thổ của họ bị đối phương xâm chiếm, khiến nhận thức ban đầu của hắn về phía bên kia và nguồn gốc cuộc chiến bị lung lay."},{"chuong":1060,"tieuDe":"Tìm Kiếm Chân Tướng","tomTat":"Thạch Hạo đi sâu vào thế giới bên kia Biên Hoang và phát hiện cư dân nơi đây thực lòng tin rằng họ mới là chủ nhân cửu thiên thập địa từng bị ma quỷ trục xuất. Sau khi bí mật tìm kiếm thức hải của nhiều người, hắn xác nhận quan niệm ấy không phải lời nói dối có chủ ý. Trong nhiều tháng du hành qua các thành trì, bộ lạc và cổ địa, hắn còn nhận ra nhiều chủng tộc vốn đã tuyệt tích ở ba nghìn Đạo Châu vẫn hưng thịnh tại đây. Những lời truyền rời rạc, di tích tàn khuyết và một hàng chữ cổ dần hé lộ rằng từng có một thời đại hắc ám đẫm máu bị cưỡng ép xóa khỏi lịch sử. Thạch Hạo tiếp tục kết giao với những người dò xét cổ sử và biết đến nhóm sinh linh được gọi là Bất Hủ người, vốn được dân bản địa tôn là chúa cứu thế và người bảo hộ. Cùng lúc đó, các đại cổ giáo đồng loạt động viên cho cuộc chiến vượt Biên Hoang, tuyên bố rằng chiến thắng sẽ giúp họ trở về cửu thiên thập địa. Khi Bất Hủ Sơn sống lại, Thạch Hạo lập tức tới đó và nhìn thấy những tàn đồ mô tả các sinh vật vô thượng từng đạt tới trạng thái bất hủ thực sự."},{"chuong":1061,"tieuDe":"Bất Hủ Sơn","tomTat":"Thạch Hạo leo Bất Hủ Sơn và khảo sát những tranh khắc mô tả bất hủ giả như Chúa cứu thế, hoàn toàn trái ngược với hiểu biết của hắn về cuộc xâm lược Cửu Thiên Thập Địa. Khi gặp những tu sĩ đã tu thành tiên khí trên sườn núi, hắn xác định tiên khí có thể làm suy yếu áp lực và biết họ tới đây để chờ bất hủ giả lựa chọn. Gần đỉnh núi, hình khắc Côn Bằng và Liễu Thần khiến hắn nghi ngờ hai cường giả từng giao chiến với lực lượng này. Một thanh niên có ba đạo tiên khí kích hoạt bia đá, bước lên con đường màu vàng và biến mất sang thế giới khác. Thạch Hạo dùng đủ ba đạo tiên khí để lên đỉnh rồi gặp lại thiếu nữ từng đi trên chiếc xe do tám ngân ngô màu bạc kéo. Thiếu nữ giải thích rằng cổ lộ dẫn tới nơi bất hủ giả cư trú và quyết định rời cố thổ dù còn lưu luyến. Lo nàng sẽ được bồi dưỡng thành đại địch của Cửu Thiên Thập Địa, Thạch Hạo cố thuyết phục nàng ở lại nhưng không thể lay chuyển niềm tin của nàng."},{"chuong":1062,"tieuDe":"Lộ Không Giống","tomTat":"Thạch Hạo nhận ra nhận thức của thiếu nữ về hai thế giới đã ăn sâu đến mức khó thể thay đổi, nên giả vờ dẫn một quyển cổ tịch để kể lại sự phá diệt của Tiên cổ và số phận của cả một kỷ nguyên bị chôn vùi. Thiếu nữ vẫn không tin, đồng thời cách giải thích đảo ngược của nàng khiến Thạch Hạo thoáng hoài nghi liệu chân tướng lịch sử mà mình biết có thể cũng đã bị bóp méo. Khi hắn cân nhắc giết hoặc phong ấn nàng để tránh hậu họa, tha tâm thông giúp nàng lập tức cảm nhận sát ý, dù không thể đọc được ký ức của một đối thủ ngang sức có tiên khí hộ thể. Một nam tử trẻ tuổi mặc giáp lam, cũng tu thành ba đạo tiên khí, lên đỉnh núi, nghi Thạch Hạo là hậu duệ ma quỷ rồi chủ động giao chiến với hắn. Hai người đấu hơn mười chiêu nhưng uy thế của Bất Hủ Sơn thức tỉnh đã buộc họ tách ra trước khi phân thắng bại. Thiếu nữ cùng nam tử giáp lam bước lên cổ lộ màu vàng, còn Thạch Hạo từ chối con đường ấy, nhanh chóng xuống núi và xé hư không để trở về thế giới của mình. Sau khi hắn rời đi, tiếng động như sóng biển cùng một tiếng hú dài chấn động trời đất vang lên, khiến khí huyết hắn sôi trào và làm hắn nghi rằng Bất Hủ đã xuất hiện."},{"chuong":1063,"tieuDe":"Trở Về","tomTat":"Thần niệm của một Bất Hủ giả vượt giới quét tới Bất Hủ sơn, khiến các thế lực dị giới chấn động, còn pháp chỉ màu vàng báo hiệu tiên chiến sắp mở ra. Các thủ lĩnh dị giới tuyên bố sẽ chuẩn bị đánh Cửu Thiên và đoạt lại những gì họ cho là thuộc về mình. Thạch Hạo tìm về dãy núi có tiết điểm không gian nhưng không thể tự mở đường, cho đến khi thần bí bảo đỉnh xuất hiện và dẫn hắn vào một vùng không gian u ám. Bảo đỉnh xóa sạch tiết điểm cùng dấu vết qua lại, khiến Thạch Hạo hoài nghi ký ức và lịch sử của cả một thế giới có thể từng bị cường giả cắt sửa. Sau khi xác nhận ký ức của Thạch Hạo vẫn được giữ lại, bảo đỉnh phá mở hư không, đưa hắn trở về vùng ngoại thành Đế Thành rồi từ biệt. Thạch Hạo nhận ra nhóm thiên tài cùng ba đại cường giả có lẽ đã rời đi từ lâu, trong khi đại thời đại chiến tranh đã thực sự mở màn. Ngay sau đó, Người áo bào tro dùng thần niệm đánh bay hắn, chất vấn quãng thời gian mất tích và đòi sưu Nguyên Thần để kiểm chứng. Thạch Hạo kiên quyết phản đối vì coi đó là sự sỉ nhục, nhưng đối phương vẫn tỏ thái độ khinh miệt trước chênh lệch thực lực giữa hai bên."},{"chuong":1064,"tieuDe":"Làm Nhục","tomTat":"Gia Đức, nam tử áo bào tro đến từ Vô Lượng Thiên, lấy danh nghĩa kiểm tra việc Thạch Hạo biến mất nhiều tháng để cưỡng ép sưu dấu ấn nguyên thần. Thạch Hạo chính thức coi Gia Đức là địch thủ, gọi ra Lôi Đế chiến y, Vạn Linh Đồ và Nghịch Long Lân để chống cự. Lôi Đế chiến y hồi sinh dưới áp lực, từ rỉ sét chuyển sang óng ánh rồi đen kịt hoàn toàn, mang ý chí và oán khí riêng, ngăn chặn Gia Đức chạm tới mi tâm Thạch Hạo. Một nhân vật khác trong Đế Thành xuất hiện can thiệp, dùng quyền ép Gia Đức dừng sưu hồn rồi giao chiến với hắn, đồng thời cảnh báo về oan khuất năm xưa từng khiến Lôi Đế chiến y hắc ám hóa. Người này chất vấn Gia Đức nhắm vào Thạch Hạo vì bất mãn khi các tiểu bối Vô Lượng Thiên bị áp chế, nhưng Gia Đức phủ nhận và viện lý do nghiêm tra. Một nhân vật cấp cao dùng uy nghiêm quát dừng cuộc nội chiến, buộc mọi người trở về thành. Cuối cùng người đã bảo vệ Thạch Hạo đưa hắn vượt qua địa vực rộng lớn đầy tinh hài tới cự thành, tức phần hạch tâm chân chính bên trong Đế Thành."},{"chuong":1065,"tieuDe":"Đế Thành Bên Trong","tomTat":"Thạch Hạo cùng Gia Đức và người áp tải dùng ba mảnh cốt hợp thành trận đài, nhờ đó tiến vào khu vực cốt lõi của Đế Thành. Tại đây, hắn nhìn thấy một không gian rộng lớn chứa nhật nguyệt, Ngân hà, đại tinh và các kiến trúc cổ, đồng thời nhận ra nhiều tu sĩ từ các cổ giới đã trấn thủ suốt thời gian dài. Khi bị hỏi về thế giới thần bí và Bất Hủ sơn, Thạch Hạo chuyển trải nghiệm của mình thành nội dung trên tranh khắc đá để che giấu chiếc đỉnh. Gia Đức vẫn muốn dựa vào cảnh giới vượt trội để cưỡng ép sưu xét Nguyên Thần hắn, dù đã được cảnh báo rằng pháp môn hóa ma đang khiến tâm cảnh bất ổn. Ông lão tóc bạc can thiệp, tát Gia Đức rồi dùng nanh sói đại bổng phá tan bảo thuật và cốt văn, đánh nát nửa người hắn trước khi buộc hắn đi bế quan. Sau đó, ông lão gọi thêm những người trấn thủ tới cùng luyện hóa, gột rửa ảnh hưởng hắc ám trên Lôi Đế chiến y và tiết lộ chủ nhân cũ của bộ giáp đã ra đi không trở lại. Cuối cùng, ông chuẩn bị đưa Thạch Hạo tới Vô Lượng Thiên, kỳ vọng hắn sớm trưởng thành rồi quay về Đế Thành thủ quan."},{"chuong":1066,"tieuDe":"Vượt Qua","tomTat":"Sau khi Gia Đức bị đưa đi giam giữ, Thạch Hạo xin gặp Diệp Khuynh Tiên và dò hỏi bí mật về biên hoang nhưng bị người trong Đế Thành kiên quyết từ chối. Tại tế đàn ngũ sắc, hắn nhận ra vật liệu của nơi này giống di tích từng thấy dưới hắc uyên trong Tiên cổ và xác định chúng đều bắt nguồn từ kỷ nguyên trước. Hắn cũng nhận thấy Đế Thành hiện tại không giống tòa thành do bảy đại vương giả trấn thủ, song ông lão tóc bạc không giải đáp nghi vấn. Ngũ sắc Truyền Tống trận sau đó xé mở thông đạo Cửu Thiên Thập Địa, đưa hắn rời ba ngàn châu và tới một cổ điện khổng lồ tại Vô Lượng Thiên. Bạch Mi lão nhân trấn giữ nơi này nhìn ra hắn có ba đạo tiên khí và tuyên bố những người được đưa tới đều phải chịu trừng phạt vì đã phạm lỗi. Thạch Hạo bị ném vào một không gian phong tỏa, nơi có nhiều thiên tài đã mắc kẹt từ vài năm tới hơn trăm năm. Không thể chấp nhận bị trì hoãn lâu như vậy, hắn quyết định phải lập tức tìm cách phá vây."},{"chuong":1067,"tieuDe":"Đăng Tiên Đài","tomTat":"Những tu sĩ bị giam nhiều năm chỉ cho Thạch Hạo cổ đạo đài ở trung tâm, nơi từng có người ngộ đạo rồi biến mất khỏi vùng giam giữ. Thạch Hạo thử dùng thần thức và lần lượt gọi ra các đạo tiên khí; đến đạo thứ ba, cổ đài lập tức phát sinh sấm chớp cùng dị tượng. Sau vài chục ngày ngộ đạo và được sức mạnh thần bí của bệ đá mài giũa, một đạo tiên khí của hắn ngưng kết thành đại đạo chi hoa ngay tại Thánh Tế cảnh. Hắn dùng bí lực của đóa hoa dẫn động cổ đài, mở thông đạo màu bạc và đưa toàn bộ tu sĩ bị nhốt ra ngoài. Khi rời đi, Thạch Hạo cúi đầu cảm tạ Bạch Mi lão nhân, đồng thời biết Thiên Thần Thư Viện đang được dự tính xây dựng tại Vô Lượng Thiên và hẹn gặp lại những thiên tài tại đó. Tuy nhiên, một cao thủ trấn thủ khu cổ địa nhận ra lai lịch của hắn rồi ép hắn tới Thái Sơ cổ quáng khai thác sinh mệnh chi thạch. Cổ quáng này vừa chứa cơ duyên kéo dài sinh mệnh vừa nổi tiếng hiểm ác, thậm chí được truyền là phần mộ của nhiều vị Tiên Vương."},{"chuong":1068,"tieuDe":"Chỉ Trích","tomTat":"Nguyên Thanh lấy việc Thạch Hạo đến Thiên Thần Thư Viện muộn và tự ý sử dụng Truyền Tống trận vượt giới làm cớ định tội hắn. Bất chấp sự phản đối của những thiên tài từng được Thạch Hạo cứu, Nguyên Thanh tuyên bố lưu đày hắn tới Thái Sơ cổ quáng, một tuyệt địa từng khiến nhiều giáo chủ mất mạng. Nguyên Thanh đánh văng những người can thiệp rồi sai sinh linh ba đầu sáu tay áp giải Thạch Hạo rời đi. Sau đó, hắn thừa nhận đã nhận lời một người khác nhằm áp chế Thạch Hạo trong mười năm, khiến đối phương bỏ lỡ giai đoạn cạnh tranh tài nguyên quan trọng nhất. Những thiên tài bị đuổi đi quyết định trở về gia tộc cầu viện và báo cho Thiên Thần Thư Viện biết Thạch Hạo đã tu thành ba đạo tiên khí. Trong khi Thạch Hạo bị đưa tới cổ quáng, nhóm thiên tài mạnh nhất tại thư viện đã hoàn thành gột rửa trong Hoàng Huyết trì và thu được lợi ích lớn. Thiên Thần Thư Viện cũng chính thức được xác lập tại Vô Lượng Thiên, trở thành nơi tập hợp kinh thư, bí pháp, tiên trì và cường giả hàng đầu để đào tạo Chí Tôn vô địch."},{"chuong":1069,"tieuDe":"Thái Sơ Cổ Quáng","tomTat":"Do tu vi đang bị phong ấn và sinh linh ba đầu sáu tay phủ vảy bạc quá mạnh, Thạch Hạo không liều mạng phản kháng, để rồi bị giao cho Xích Huyết hào đổi lấy thiên tài địa bảo. Hắn bị nhốt cùng đông đảo nô lệ trên bảo thuyền hải tặc khét tiếng, theo thuyền vượt tinh không tới khu vực Thái Sơ cổ quáng để khai thác thần liệu. Trên đường đi, Xích Huyết hào phải thận trọng băng qua phế tích của một sát trận cổ, nơi một chiếc thuyền tham lấy tàn vật phát sáng đã bị phá hủy cùng toàn bộ người trên đó. Đoàn người sau đó tới Thái Sơ tinh, hành tinh được cho là do các giáo luyện hóa từ vùng đất rộng mười vạn dặm quanh cổ quáng rồi đưa ra vực ngoại. Thái Sơ cổ quáng bất ngờ thức tỉnh, tạo ra trường vực rộng lớn và hóa thành hố đen hút hàng loạt đại tinh, buộc chủ Xích Huyết hào trực tiếp điều khiển thuyền tháo chạy. Khi dị động chấm dứt, các thuyền quay lại hành tinh và tiếp tục chuẩn bị khai khoáng. Những người có mặt đưa ra nhiều giả thuyết về các bóng người trong mỏ, còn chủ thuyền cho biết cổ quáng đã tồn tại từ thời Tiên cổ hoặc sớm hơn, từng bị lấp rồi được đào lại trong kỷ nguyên hiện tại."},{"chuong":1070,"tieuDe":"Nô Lệ","tomTat":"Tiếng ca thê lương vang lên từ Thái Sơ Cổ Quáng, khiến nhiều cao thủ cùng cảm ứng cảnh một nữ tử tuyết y đạp trăng đăng tiên giữa vô số anh hùng ngã xuống. Không có ai thực sự bước ra khỏi cửa động, nhưng dị tượng làm các đại nhân vật nghi ngờ một sinh linh cổ xưa hoặc Tiên vương chôn trong Vạn Vật Thổ đã thức tỉnh. Xích Huyết hào vội rời Thái sơ ngôi sao, bỏ lại gần mười vạn người để các thế lực khai khoáng chia nhau làm nô lệ, trong đó Thạch Hạo cùng vài nghìn người bị một Cổ thế gia mua lại. Nguyên Thanh biết tin và quyết định lợi dụng hiểm cảnh tại cổ khoáng để gián tiếp xóa bỏ Thạch Hạo thay vì chỉ áp chế hắn mười năm. Khi Cổ thế gia kiểm tra, kỳ thạch dò xét bị lực lượng trong cơ thể Thạch Hạo nghiền thành bột, còn nỗ lực đọc ký ức của hắn bị cấm chế Nguyên Thần ngăn chặn. Thạch Hạo tự xưng là Đế, dựng lai lịch xuất thân Đại Hoang và chủ động phô bày hai đạo tiên khí nhưng vẫn che giấu thực lực thật. Cổ thế gia vì thế đề nghị đưa hắn tới Thiên Thần thư viện nếu hắn chấp nhận đi theo vị tiểu thư mang vô thượng tiên huyết của gia tộc."},{"chuong":1071,"tieuDe":"Điều Kiện","tomTat":"Các trưởng giả trấn thủ khu mỏ tiết lộ Vương tộc là một Trường Sinh gia tộc lưu truyền từ Tiên cổ, có thủy tổ từng bước vào lĩnh vực Tiên đạo nhưng đã chết trận. Họ đề nghị đưa Thạch Hạo tới Thiên Thần Thư Viện dưới danh nghĩa chiến phó của tiểu thư mang tiên huyết, với điều kiện hắn phải đi theo cô và không được phản bội bộ tộc. Qua đó, Thạch Hạo hiểu Nguyên Thanh đày mình tới cổ khu mỏ không chỉ để hại mạng mà còn nhằm khiến hắn bỏ lỡ giai đoạn tranh đoạt tài nguyên và quật khởi quan trọng nhất. Vương tộc hứa giúp hắn thoát thân phận nô lệ nếu hắn vào Thái Sơ cổ quáng tìm một hoặc hai khối Sinh mệnh chi thạch cho tiểu thư. Thạch Hạo chấp nhận mạo hiểm vì muốn tận dụng Sinh mệnh chi thạch và tiên khí trong cổ quáng để bù lại thời gian đã mất, nhưng yêu cầu được chuẩn bị đầy đủ bí bảo hỗ trợ. Các trưởng giả tháo gông xiềng và giải cấm chế cho hắn, đồng thời đội Kim Cương trác lên đầu hắn để ngăn hắn bỏ trốn. Sau vài ngày chuẩn bị, Thạch Hạo mang theo những vật phẩm cần thiết và lên đường tiến vào Thái Sơ cổ quáng."},{"chuong":1072,"tieuDe":"Tiến Vào Mỏ Khoáng","tomTat":"Thạch Hạo vượt qua vùng núi khô héo và khu khai thác trên Thái Sơ tinh để tiến về trung tâm Thái Sơ cổ quáng. Trên đường, hắn chứng kiến gió xoáy đen, ánh sáng từ hư không và nhiều dị tượng trường vực liên tiếp giết người. Mấy chục tử sĩ của các thế gia và cổ giáo bắt kịp hắn, nhưng hơn hai mươi người bị mưa sáng xuyên thủng thân thể lẫn Nguyên Thần trước cửa mỏ. Nhờ tiên khí ngăn cản ánh sáng, Thạch Hạo phóng thích hai đạo tiên khí rồi chủ động bước vào cổ quáng, trong khi toàn bộ những người nhảy theo đều chết giữa đường. Ở gần lối vào, Vạn Linh Đồ tự hiện lên bảo vệ hắn trước khí tức của một xác ướp cổ mặc thiên thiền bảo y. Thạch Hạo từ bỏ ý định lấy bảo y vì không thể tiếp cận thi thể an toàn. Khi tiếp tục quan sát nơi sâu trong mỏ, hắn nghe thấy tiếng hát du dương mang khí tức an lành và nghi ngờ người hát là một sinh linh còn sống."},{"chuong":1073,"tieuDe":"Thăm Dò Bí Mật","tomTat":"Thạch Hạo trấn tĩnh sau tiếng ca phiêu miểu, mở Thiên mục tìm Sinh mệnh chi thạch rồi chọn con đường rộng nhất để tiến sâu vào hệ thống hang động như mê cung của Thái Sơ cổ quáng. Trên đường, hắn gặp nhiều thi hài bất hủ và những xác ướp đã sinh ra chút linh trí, trong đó có một con nhện đen đã chết nhưng vẫn sở hữu sức mạnh vượt trên Giáo chủ. Hắn tiếp tục phát hiện một kim sắc nhện lớn nằm trên mạng tơ vàng, có thi khí đủ nghiền nát pháp khí Thiên thần. Khi thử lấy tơ nhện, Thạch Hạo khiến thi hài này chuyển động và bị một đòn đánh văng vào vách đá, gãy hơn mười chiếc xương cùng tổn thương phủ tạng dù có Vạn Linh Đồ hộ thể. Tiếp tục lần theo sinh khí và dược hương, hắn nhìn thấy vô số thiên binh thiên tướng đi trên một cổ lộ cụt giữa hư không và hỗn độn nhưng không thể tới gần. Cuối cùng, Thạch Hạo tới vùng đầy quang vũ và ráng màu, nơi không còn thi hài, rồi xác định sâu trong cổ khoáng có một cây bất hủ tiên dược nghi là Trường Sinh dược."},{"chuong":1074,"tieuDe":"Trường Sinh Dịch","tomTat":"Thạch Hạo tiến sâu trong Thái Sơ cổ quáng, gặp một cây Trường Sinh dược vừa niết bàn hóa thành thú nhỏ nhưng không thể ngăn nó xé hư không đào thoát. Mùi thơm còn lưu lại dẫn hắn trở về ao nước, nơi lá, thân, rễ và lớp thân cũ của tiên dược đang hòa tan cùng thần tuyền để tạo thành Trường Sinh dịch. Hắn bố trí trận pháp giữ tinh khí rồi uống nước thuốc, khiến xương gãy và phủ tạng bị thương nhanh chóng khép lại, vì vậy quyết định ở lại cổ quáng chữa thương và tu hành. Tại Thiên Thần Thư Viện, những thiên tài được cứu khỏi Đăng Tiên Đài báo rằng Hoang còn sống nhưng đã bị Nguyên Thanh đày tới Thái Sơ cổ quáng, khiến cao tầng lập tức phái người cứu viện. Trong khi Tào Vũ Sinh, Thái Âm Ngọc Thỏ và Trường Cung Diễn lo lắng, nhiều kỳ tài khác cho rằng Thạch Hạo đã tới quá muộn và bỏ lỡ những tài nguyên Tiên đạo tốt nhất. Đội cứu viện bí mật tới Thái Sơ tinh, biết hắn từng bị bán làm nô lệ rồi đưa vào cổ quáng nhưng chờ hơn nửa tháng vẫn không thấy người trở ra. Khi họ quay về báo cáo, phần đông trong thư viện tin rằng Hoang đã chết và truyền kỳ của hắn đã kết thúc, còn Nguyệt Thiền biểu lộ tâm trạng phức tạp mà không biết hắn đang âm thầm hưởng một cơ duyên lớn."},{"chuong":1075,"tieuDe":"Thư Viện Phong Vân","tomTat":"Tin Hoang tử nạn tại Thái Sơ cổ quáng làm Thiên Thần Thư Viện chấn động, khiến Thanh Y đau buồn đến mức chấp nhận hợp nhất với Nguyệt Thiền và yêu cầu tương lai phải giết Nguyên Thanh. Nguyệt Thiền hoãn việc dung hợp cho đến khi cả hai mạnh hơn, đồng thời muốn Thanh Y chém bỏ ký ức về Hoang. Tào Vũ Sinh, Thái Âm Ngọc Thỏ, Tần Hạo, Trường Cung Diễn, Long Nữ và Thạch Nghị đều phản ứng trước tin dữ, trong khi một hậu duệ tiên nhân tóc lục công khai thách thức Hoang nếu hắn còn sống. Cao tầng thư viện lập lại trật tự, cấm gây hấn và báo thù nhưng mở cơ hội cho học viên tự nguyện đến Thái Sơ cổ quáng rèn luyện với sự viện trợ của thư viện. Trái với tin đồn bên ngoài, Thạch Hạo đã chữa lành thương thế và bế quan hơn nửa tháng trong một ao Trường Sinh dịch sâu trong cổ quáng. Khi hắn vận chuyển cốt văn, ba đạo tiên khí đồng thời hiện lên, đại đạo chi hoa hấp thu khí tức Tiên đạo rồi thai nghén một tiểu nhân ngồi xếp bằng trên cánh hoa."},{"chuong":1076,"tieuDe":"Tu Ra Một Cái Quái Vật","tomTat":"Đại đạo chi hoa của Thạch Hạo liên tục nở rồi tàn dưới sự tẩm bổ của Trường Sinh Dịch, cuối cùng thai nghén một sinh linh hình người phát ra thần mang và khí thế kinh động Thái Sơ cổ quáng. Sau hơn nửa tháng bế quan, Thạch Hạo tỉnh lại, dùng Thiên mục quan sát và phát hiện sinh linh giống mình nhưng không chịu sự khống chế, quanh thân còn có những mảnh vỡ thời gian khiến hắn nghi nó tồn tại trong quá khứ. Hắn nhận ra Trường Sinh Dịch chỉ xúc tiến lột xác, còn đạo quả này chính là kết quả từ con đường riêng của mình, rồi quyết định tiếp tục bế quan để thử ngưng tụ đóa Đại đạo chi hoa thứ hai. Trong khi đó, người ngoài nhìn dị tượng tại cổ khoáng và cho rằng Thạch Hạo cùng những người tiến vào trước đó khó còn sống sót. Một cốt thuyền của Thiên Thần Thư Viện đưa nhiều hậu bối ưu tú cùng hai lão giả hộ đạo tới Thái Sơ tinh để rèn luyện. Tào Vũ Sinh đưa chân dung Thạch Hạo ra truy hỏi và được người Vương gia xác nhận rằng hắn đã xuống cổ khoáng nhưng chưa trở lại, khiến Long Nữ lo ngại hắn đã chết. Khi một số thiên tài Cửu Thiên chế giễu Hoang và Ba ngàn đạo châu, Thái Âm Ngọc Thỏ nổi giận, thách họ tiến vào cổ khoáng và quả quyết họ sẽ bị Thạch Hạo đánh bại thảm hại nếu gặp hắn."},{"chuong":1077,"tieuDe":"Cửu Hoàng Lô","tomTat":"Thái Âm Ngọc Thỏ và Tào Vũ Sinh tiếp tục đối đáp với những thiên tài xem thường Hoang cùng tu sĩ Ba ngàn đạo châu, buộc hai trưởng lão Thiên Thần Thư Viện phải dẹp tranh chấp và cấm môn đồ thù hằn, chém giết. Các trưởng lão tuyên bố việc thăm dò Thái Sơ cổ quáng hoàn toàn tự nguyện, giới hạn mỗi lượt năm người và đưa Cửu Hoàng lô ra làm vật hộ thân. Chí bảo đỏ sẫm mang dấu chín Phượng Hoàng này từng bị một nhân vật vô địch ngoài biên hoang xuyên thủng, nhưng vẫn có uy năng mạnh mẽ và vốn được đào lên từ chính cổ khoáng. Nữ tu áo tím Nguyệt Tê tộc cùng bốn nam tu trở thành nhóm đầu tiên tiến vào, hợp lực thúc giục cốt văn khiến chín Phượng Hoàng cùng sương hỗn độn tạo trường vực bảo hộ. Nhờ Cửu Hoàng lô, họ sống sót trước uy áp của một thi hài lão đạo tóc bạc đủ khiến Thiên Thần sụp đổ, dù bảo lô từng rung động dữ dội vì hô ứng với nơi này. Trên đường đi sâu, cả nhóm khẳng định Hoang đã chết và muốn tìm di vật của hắn để chế nhạo Thái Âm Ngọc Thỏ. Nhưng ngay sau đó, họ nhìn thấy Thạch Hạo với tinh thần sung mãn và thân thể hoàn mỹ bước ra từ một bảo trì, lạnh lùng nhìn những kẻ vừa buông lời khinh miệt mình."},{"chuong":1078,"tieuDe":"Quái Vật","tomTat":"Năm truyền nhân đến từ Vô Lượng Thiên bất ngờ gặp Thạch Hạo còn sống trong Thái Sơ cổ quáng và phát hiện tiên dược trì phía sau hắn. Nhận ra đây là tạo hóa do Trường Sinh dược lột xác để lại, họ nảy lòng tham, khinh miệt xuất thân Ba ngàn đạo châu của Hoang và định dùng Cửu Hoàng Lô giết hắn. Thạch Hạo chủ động áp sát, đá một đối thủ hộc máu nhưng người này được lực phòng hộ do chín Phượng Hoàng tạo thành cứu mạng. Khi năm người toàn lực thúc giục thần lô, Thạch Hạo mặc Lôi Đế chiến y, cầm Nghịch Long Lân và ném Vạn Linh Đồ ra đối kháng. Vạn Linh Đồ chịu được sức ép của chín Chân Hoàng rồi tình cờ đánh trúng lỗ thủng do trận chiến tại Biên Hoang để lại, khiến Cửu Hoàng Lô suy yếu. Sau khi xác nhận thần lô không có khí linh, Thạch Hạo thu hồi Vạn Linh Đồ và lao vào cận chiến. Một chưởng mang Côn Bằng lực của hắn bao phủ cả năm đối thủ, khiến họ dù đồng loạt vận dụng tiên khí vẫn ho ra máu và kinh hãi coi Hoang là một quái vật."},{"chuong":1079,"tieuDe":"Quét Ngang","tomTat":"Nữ tu Nguyệt Tê tộc thi triển Linh Tê ngự nguyệt, dùng Thần Nguyệt chứa thức niệm bảo thuật tập kích nguyên thần Thạch Hạo, nhưng bị đại đạo chi hoa của hắn phá giải. Thạch Hạo sau đó lần lượt vận dụng Côn Bằng lực, Lôi Đế chỉ và quyền Luân Hồi, đánh bại toàn bộ năm cao thủ Vô Lượng Thiên rồi trấn áp họ. Hắn chưa giết năm người vì lo hành động này sẽ khiến mình mất cơ hội gia nhập Thiên Thần Thư Viện. Cửu Hoàng lô không bảo vệ họ mà tự bay về lối ra, đồng thời cộng hưởng với cổ khoáng và đánh thức lực lượng kỳ dị trong nơi sâu xa. Thạch Hạo mở Thiên mục, nghe thấy tiếng tụng kinh Lục Đạo Luân Hồi đại pháp và nhận ra đó là tuyệt học của Chí Tôn cung điện. Phát hiện này khiến hắn vừa kích động vì cơ hội đạt được thiên công, vừa nghi ngờ những bí mật đang bị chôn giấu trong cổ khoáng."},{"chuong":1080,"tieuDe":"Tù Binh Một Đám","tomTat":"Cửu Hoàng Lô tự thoát khỏi Thái Sơ cổ quáng và bay về mặt đất, bốc lửa, phát tiếng phượng hót cùng dị tượng chín Chân Hoàng như thể khí linh đang thức tỉnh. Thấy hồn đăng của năm đệ tử đầu tiên vẫn cháy, các trưởng lão Thiên Thần Thư Viện lần lượt phái thêm những đội năm người xuống mỏ để cứu viện và tìm kiếm cổ kinh. Ở sâu trong cổ khoáng, Thạch Hạo nghe tiếng tụng Lục Đạo Luân Hồi Thiên Công nhưng tạm dừng tiếp cận vì trực giác cảnh báo nguy cơ hình thần đều diệt. Hai đội thiên tài đến sau không tin Hoang đã đánh bại nhóm đi trước, từ chối tự phong và đều nhanh chóng bị hắn trấn áp. Cửu Hoàng Lô nhiều lần tự bay trở lại mặt đất khiến người bên ngoài hiểu lầm rằng những người mất tích vẫn đang lĩnh hội cơ duyên, cho tới khi cả ba lượt thám hiểm đều không trở về. Thạch Hạo giữ mạng cho hơn mười tù binh, phong tỏa họ trong mỏ rồi thu toàn bộ Trường Sinh dược trì cùng thần dịch vào pháp khí. Sau đó, hắn rời nơi tu hành và tiến sâu vào cổ khoáng để tìm Lục Đạo Luân Hồi Thiên Công."},{"chuong":1081,"tieuDe":"Thiên Công","tomTat":"Mười lăm thiên tài Thiên Thần Thư Viện hoảng sợ cầu cứu khi di hài nhện đen đe dọa họ, khiến Thạch Hạo quay lại dùng cành vàng gom cả nhóm và dựng trận pháp bảo vệ. Di hài nhện tiếp tục truy đuổi hắn nhưng run rẩy phủ phục trước vùng tối từng phát ra tiếng tụng kinh, còn Thạch Hạo vẫn quyết tiến sâu để tìm Lục Đạo Luân Hồi Thiên Công. Mang theo Vạn Linh Đồ và Lôi Đế chiến y, hắn chịu sát ý vô hình rồi bị tiếng gầm của một di hài cổ sư trăm trượng đánh đến ho ra máu và thất khiếu chảy máu. Các bảo vật giúp hắn sống sót, còn cổ sư biến mất vào bóng tối và để lại vài sợi lông cứng hơn thép. Tiếng gầm làm ngoại giới rung chuyển, khiến hai trưởng lão Thiên Thần Thư Viện lo sợ những bí mật bị chôn trong Thái Sơ cổ quáng tái hiện. Thạch Hạo tiếp tục vượt qua hắc uyên chứa nhiều di hài mạnh mẽ và cầm thêm Nghịch Long Lân để phòng bị. Cuối đường, hắn cưỡng ép tiến vào một cung điện cổ màu đen có uy áp gần nghiền nát thân thể, rồi nhìn thấy sáu bóng người mang sáu tư thế tu hành hoặc kết ấn khác nhau và liên tưởng đến Lục Đạo Luân Hồi."},{"chuong":1082,"tieuDe":"Lục Đại Cường Giả","tomTat":"Trong cung điện cổ màu đen, Thạch Hạo đối diện sáu sinh linh hình người có khí thế đáng sợ và nghi những tư thế của họ là thức mở đầu của Lục Đạo Luân Hồi Thiên Công. Vì không có kinh văn hoàn chỉnh, hắn cưỡng ép phỏng đoán đến mức Nguyên Thần ảm đạm, ho ra máu và suýt tẩu hỏa nhập ma, nhưng kịp tỉnh táo để dừng lại. Sau đó, hắn nhận ra sáu bóng người thực chất là những di thể còn nguyên máu thịt, thuộc nhiều độ tuổi và có thể đến từ các thời đại khác nhau. Được Lôi Đế chiến y và Vạn Linh Đồ bảo vệ, Thạch Hạo tiến gần khảo sát rồi phát hiện một thiếu niên đã bị mũi tên đen xuyên thủng Nguyên Thần, còn một người trung niên từng bị đánh vỡ mi tâm và xương trán. Những thương tích này cho thấy sáu cường giả đã trải qua một trận chiến vô cùng thảm khốc. Cuối cùng, phù hiệu giống dấu ấn Tội Huyết lóe lên tại mi tâm người thứ sáu, khiến Thạch Hạo nghi ngờ di thể này có thể là tổ tiên của một mạch Tội Huyết."},{"chuong":1083,"tieuDe":"Lục Đạo Luân Hồi","tomTat":"Trong cung điện cổ màu đen, Thạch Hạo nhận ra một trong sáu thi thể tuyệt đại cường giả mang phù hiệu Tội Huyết tương đồng với mình. Dùng Võ đạo Thiên nhãn quan sát, hắn phát hiện bên trong thi thể là vô số thương tích khủng khiếp và từ đó cảm nhận cảnh người này từng bị quần địch vây công, tử chiến bảo vệ một tòa thành tại Biên Hoang. Sau khi hành lễ, Thạch Hạo tái hiện phần văn tự Lục Đạo không trọn vẹn từng thu được tại Hư Thần giới, khiến cổ điện cùng sáu thi thể cộng hưởng nhưng chỉ phát ra kinh âm mơ hồ. Tiếng tụng kinh truyền ra ngoài làm các thiên tài Thiên Thần Thư Viện và nhiều thế lực thèm muốn, song không ai dám tiến vào cổ quáng. Không cam lòng bỏ cuộc, Thạch Hạo thúc giục khí huyết để phù hiệu Tội Huyết trên mi tâm hiện ra. Dấu ấn trên xương trán thi thể thức tỉnh và nối liền với phù hiệu của hắn, tạo nên sự giao cảm giữa người sống và người chết. Nhờ đó, tiếng tụng Lục Đạo Luân Hồi Thiên Công trở nên hoàn toàn rõ ràng trong thần thức, mở đầu quá trình Thạch Hạo một mình phá giải truyền thừa."},{"chuong":1084,"tieuDe":"Ngộ Pháp","tomTat":"Thạch Hạo tập trung lắng nghe Lục Đạo Luân Hồi Thiên Công, cưỡng ép ghi nhớ những đoạn kinh văn tối nghĩa và cảm nhận cảnh tượng vạn vật hưng suy qua nhiều kỷ nguyên. Hàm nghĩa Luân Hồi ban đầu xung đột với niềm tin của hắn về sự bất diệt và tiếp nối của bản thân, nhưng hắn quyết định tu luyện để hiểu rõ chân nghĩa trước khi phân định. Trong trạng thái ngộ đạo, Thạch Hạo mất cảm giác về thời gian, gần như lạc mất chính mình rồi chấn động thổ huyết. Hắn mô phỏng tư thế của sáu đại cường giả và lần lượt thi triển được những thức mở đầu trước đây không thể hiểu nổi. Các thức này diễn hóa thiên đạo, quỷ đạo, Địa, Hỏa, Phong, Thủy cùng vòng tuần hoàn của vật chất và sinh mệnh, giúp hắn nhận ra Lục Đạo không có một cách giải thích cố định. Sau khi hóa giải mâu thuẫn trong nhận thức, Thạch Hạo tu thành sáu thức mở đầu và đạt thực lực vượt qua chính mình trước kia."},{"chuong":1085,"tieuDe":"Diệt Độ","tomTat":"Trong cung điện cổ màu đen, Thạch Hạo luyện thành sáu thức mở đầu của Lục Đạo Luân Hồi Thiên Công, tạo nên dị tượng phong vũ lôi điện, tinh tú, sinh vật cổ và núi sông vạn vật. Sau khi ghi nhớ kinh văn, hắn rời cung điện và lần lượt chứng kiến Thiên hạt cấp Chí Cường giả, cổ sư dính máu đen cùng một đội xác ướp mặc giáp tiến vào thông đạo quỷ dị giữa hư không. Tại vùng sâu phủ khói xám, hắn cảm nhận một tồn tại chí cao đang ngồi xếp bằng và nhận ra sức mạnh nơi đó có thể nhằm vào Vạn Linh Đồ, nên chủ động dừng thăm dò. Thạch Hạo sau đó đọc những hình khắc ghi lại việc người xưa khai thác tiên kim, liên tục gặp các cái chết ly kỳ rồi phải lấp kín và phong ấn toàn bộ Thái Sơ cổ quáng. Vì bên ngoài đang có nhiều thế lực theo dõi, hắn ở lại củng cố thiên công và suy ngẫm cách điều khiển nhiều loại bảo thuật. Hắn ngâm mình trong Trường Sinh dược dịch, vận chuyển cốt văn cùng Nguyên thủy chân giải để chữa ám thương, luyện thể và tu Nguyên Thần. Khi toàn bộ dược lực và Tiên Đạo khí tức bị hấp thu, thân thể hắn nứt vỡ, xương gãy và nội tạng suy tối trong trạng thái diệt độ, nhưng thần quang lập tức bắt đầu tuôn ra từ các khe nứt, mở đầu quá trình niết bàn tân sinh."},{"chuong":1086,"tieuDe":"Tân Sinh","tomTat":"Thạch Hạo chủ động quan sát quá trình niết bàn khốc liệt khi xương cốt gãy vụn, ngũ tạng tan thành năm luồng Tiên Thiên tinh khí và thân thể mất đi trạng thái nguyên vẹn. Từ sự diễn hóa Ngũ hành của ngũ tạng, hắn bắt đầu suy ngẫm về con đường tự sáng tạo một hệ thống tu luyện khác biệt trong tương lai. Sau khi thay máu, đổi da, tái tạo phủ tạng và chân cốt, nguyên thần của hắn cũng phá lớp ngoài để tân sinh, khiến thể phách, thần giác và sức mạnh đều vượt xa trước đó. Cùng lúc, hơn mười học sinh Thiên Thần Thư Viện tiến vào khu vực an toàn của Thái Sơ cổ quáng tìm kiếm đồng môn mất tích rồi phát hiện ao niết bàn của hắn. Một số người nghi ngờ Thạch Hạo biết tung tích đồng môn nên định bắt hắn khi quá trình lột xác chưa hoàn tất, đồng thời dựa vào Cửu Hoàng lô để trấn áp. Thạch Hạo vừa niết bàn viên mãn liền đứng dậy, cầm Vạn Linh Đồ và thi triển thức mở đầu của Lục Đạo Luân Hồi Thiên Công để đồng thời điều động sáu loại bảo thuật. Cửu Hoàng lô mất hiệu lực, toàn bộ nhóm thiên tài bị đánh bay và trọng thương, còn một cô gái kinh ngạc nhận ra cổ thiên công đã tái hiện nhân gian."},{"chuong":1087,"tieuDe":"Cướp Sạch Thiên Tài","tomTat":"Thạch Hạo dùng một thức cổ thiên công đánh bại hơn mười thiên tài được chọn vào Thiên Thần Thư Viện, khiến họ phải thừa nhận hắn đủ sức sánh với những người mạnh nhất như Lục Đà. Nhóm chiến bại nhận ra hắn chính là Hoang, người từng bị Nguyên Thanh bắt và đưa vào cổ khoáng để áp chế trong mười năm. Thạch Hạo không giết họ vì kiêng dè các thế lực lớn đứng sau và muốn giữ lại những người có tiềm lực cho biến loạn Biên Hoang, nhưng vẫn lục soát toàn bộ tài vật, lấy Hoàng Huyết, hàng chục bán thần quả cùng nhiều bảo vật khác. Những người chống đối, kể cả hai thiếu nữ đã tu thành hai đạo tiên khí, đều bị đánh và cướp sạch. Trước khi rời cổ khoáng để tới Thiên Thần Thư Viện, hắn ép cả nhóm tự xóa ký ức; một thanh niên phản đối bị đánh ngất bằng bạch cốt bổng rồi chém bỏ một phần dấu ấn thần hồn. Cuối cùng cả nhóm đều bị khuất phục và rơi vào trạng thái ảm đạm, nhưng vụ cướp sạch vẫn là chuyện rất khó quên."},{"chuong":1088,"tieuDe":"Nhân Vật Kinh Khủng","tomTat":"Thạch Hạo tìm được nhóm thiên tài còn lại của Thiên Thần Thư Viện và biết tin đồn Phong tộc từng thỉnh cầu Nguyên Thanh áp chế mình, trong đó Phong Hành Thiên là kỳ tài đã tu thành ba đạo tiên khí. Sau khi cướp bảo vật và chém bỏ ký ức liên quan của họ, hắn tiến sâu vào Thái Sơ cổ quáng nhưng bị bầy cổ thú chặn đường, buộc phải chạy vào khu vực nguy hiểm hơn. Hai trưởng lão Thiên Thần Thư Viện chia nhau hành động, một người mang Cửu Hoàng lô vào cứu hơn ba mươi học sinh bị giam, còn người kia ở ngoài tiếp ứng. Trưởng lão trong cổ khoáng đuổi theo bầy thú và nhận ra một sinh linh hình người là vô thượng cường giả từ kỷ nguyên trước, vì thế lập tức bỏ chạy. Thạch Hạo cũng cảm nhận nguy hiểm không thể chống lại nên trốn vào cung điện cổ màu đen, đứng cạnh Lục Đạo cường giả và cầm Vạn Linh Đồ chờ đợi. Sinh linh hình người truy đến nhưng kiêng kỵ cổ điện, chỉ do dự bên ngoài rồi cùng bầy thú rời đi. Nhận ra Thiên Thần chỉ là điểm khởi đầu trên con đường tu hành, Thạch Hạo quyết định đến Thiên Thần Thư Viện tăng cao thực lực và rời khỏi cổ khoáng khi bên ngoài đã yên tĩnh."},{"chuong":1089,"tieuDe":"Lén Qua","tomTat":"Thạch Hạo sống sót trở lại mặt đất sau nhiều ngày mắc kẹt trong Thái Sơ cổ quáng, đồng thời hồi tưởng những bí mật và hiểm họa dưới lòng đất. Hắn xác định cổ thiên công là thu hoạch quan trọng nhất, còn Trường Sinh nước thuốc đã giúp mình hoàn thành một lần đại niết bàn, tăng mạnh thân thể và lực lượng tinh thần. Vì không thể tự vượt qua tinh vực cổ chiến trường để về Vô Lượng Thiên, hắn ẩn mình theo dõi các căn cứ quanh Thái Sơ ngôi sao và chờ một chiến thuyền thuận đường. Kim Cương trác vẫn khóa trên đầu hắn, lại có dấu hiệu tự nổ khi bị Đại La Tiên Kiếm tác động nên chưa thể tháo bỏ. Khi một nô lệ thuyền màu lam tới nơi, Thạch Hạo dùng Thất Thập Nhị Biến đổi dung mạo, trà trộn vào đám đông và nộp thiên tài địa bảo để vượt qua kiểm tra. Sau khi thuyền rời đi, người của Vương gia cảm ứng được dao động của Kim Cương trác nhưng chưa dám xác nhận Thạch Hạo còn sống. Chiến thuyền cuối cùng đưa hắn trở lại Vô Lượng Thiên, nơi hắn quyết tiến vào Thiên Thần Thư Viện và quật khởi."},{"chuong":1090,"tieuDe":"Thiên Thần Thư Viện","tomTat":"Thạch Hạo đặt chân lên cổ đại lục Vô Lượng Thiên rồi rời chiến thuyền màu xanh lam trước khi người của Vương gia đuổi tới kiểm tra. Ông lão Vương gia dùng chiến thuyền màu tím chặn chiếc thuyền xanh lam để tìm nô bộc đào tẩu, nhưng không thu được kết quả vì Thạch Hạo cùng một nhóm người đã xuống thuyền từ trước. Không biết mình đang bị truy tìm, Thạch Hạo liên tục sử dụng các Truyền Tống trận, trả nhiều thiên tài địa bảo và mất nửa tháng mới tới Tinh Thần hải. Tại đây, hắn biết vùng đất rộng lớn này được tạo thành từ vô số sao băng của một trận đại chiến cổ xưa và còn chôn vùi nhiều di vật cùng tiên gia động phủ. Thiên Thần Thư Viện tọa lạc tại vùng cát địa nhất, có sơn môn tráng lệ, thần dược, cổ thần giao và một tiên gia động phủ từ kỷ nguyên trước được truyền là sắp xuất thế. Ngoài sơn môn tụ tập vô số tuấn kiệt và hậu duệ thế lực lớn, nhưng Thạch Hạo nhanh chóng biết kỳ tuyển đệ tử chính thức đã kết thúc. Những người này thực chất đang tranh cơ hội trở thành người theo đuổi, tôi tớ hoặc hầu gái của các đệ tử nòng cốt, với hy vọng nhờ biểu hiện xuất sắc mà được nhận vào thư viện và tiếp cận truyền thừa mạnh nhất trong lịch sử."},{"chuong":1091,"tieuDe":"Kẻ Bị Ruồng Bỏ","tomTat":"Thạch Hạo cùng đông đảo thiên tài đứng chờ ngoài sơn môn Thiên Thần Thư Viện, nơi nhiều người mong được đệ tử chính thức tuyển làm người theo đuổi để tiếp cận chân truyền. Trong lúc chờ đợi, đám đông bàn luận về uy thế của các Trường Sinh thế gia cùng những minh châu thuộc Vương gia và Ninh gia. Triệu Cương cưỡi sáu dực cổ thú tới khiêu chiến vì từng bị hủy tư cách do bỏ lỡ thời hạn báo danh, nhưng hắn tiếp tục bị nhóm học sinh trấn giữ sơn môn liên thủ đánh lui. Sau đó, Mạnh Vân xuất hiện với Ngọc Kiếm và một mình đánh bại chính nhóm học sinh ấy; nàng cũng là thiên tài bị chặn ngoài cửa vì đến không đúng hạn. Chứng kiến tình cảnh của hai người, Thạch Hạo nhận ra việc mình đến muộn nhiều tháng có thể khiến hắn bị từ chối nhập viện. Những người quá hạn nghiêm trọng bị gọi là kẻ bị ruồng bỏ, dù có người suy đoán thư viện chỉ đang cố ý mài giũa họ."},{"chuong":1092,"tieuDe":"Tuyệt Diễm","tomTat":"Mạnh Vân đánh trọng thương một người trong nhóm vây công, nhưng lập tức rút lui khi Lục Đà cùng các tinh anh Thiên Thần Thư Viện xuất hiện. Sơn môn trở nên náo nhiệt khi các đệ tử nòng cốt công khai tuyển người theo đuổi, còn Thạch Hạo nhận ra Nguyên Thanh có thể dùng quyền lực để cản trở mình gia nhập thư viện. Phong Hành Thiên xuất hiện giữa nhiều cao thủ và cảm ứng được ánh nhìn dò xét của Thạch Hạo. Yêu Nguyệt cũng nhận ra lực lượng tinh thần của hắn, sau đó thu nhận Bạch Hoành khi thiên kiêu Bạch Hổ tộc tự nguyện hóa bản thể kéo xe. Cuối cùng, Vương Hi của Vương gia tới chọn tôi tớ, nhận ra Thạch Hạo đang mang Kim Cương trác do người trong tộc đeo lên và trực tiếp đi về phía hắn."},{"chuong":1093,"tieuDe":"Vương Hi Tiên Tử","tomTat":"Vương Hi xuất hiện trước sơn môn Thiên Thần Thư Viện và nhờ linh giác của người Vương gia mà nhận ra Kim Cương Trác hàng nhái đang giam cầm Thạch Hạo. Tưởng hắn là nhân tuyển tôi tớ do trưởng lão trong tộc chuẩn bị, nàng nhiều lần đề nghị đưa hắn vào thư viện nhưng đều bị từ chối. Vương Hi dùng sương trắng thử sức, còn Thạch Hạo âm thầm vận dụng hai đạo tiên khí hóa giải, khiến nàng phải nhìn nhận hắn như một cao thủ hiếm thấy. Nàng cho biết thư viện đã ngừng tuyển người và ngay cả Hoang, người tu thành ba đạo tiên khí, cũng có nguy cơ không được tiếp nhận vì đến muộn. Khi Nguyên Thanh công khai đưa một hậu nhân vào viện, Thạch Hạo nghi ngờ chuyện mình từng bị áp chế mười năm có liên quan đến một cuộc trao đổi lợi ích và nảy ý định từ bỏ thư viện để giữ tôn nghiêm. Từ sâu trong Thiên Thần Thư Viện, một người quát hỏi tội Nguyên Thanh, nhưng một người khác lập tức bảo ông rời đi trước, hé lộ sự chia rẽ trong tầng cao."},{"chuong":1094,"tieuDe":"Vào Thư Viện","tomTat":"Nguyên Thanh bị lực lượng vô hình trong sơn môn tác động và phải phát kim quang chống đỡ, nhưng sau khi được một tiếng nói già nua triệu vào đảo thần, hắn vẫn trở ra mà không bị trấn áp hay trách phạt nghiêm khắc. Hậu nhân do Nguyên Thanh đưa tới cũng được giữ lại làm đệ tử, khiến Thạch Hạo phẫn nộ và từng muốn rời khỏi Thiên Thần Thư Viện. Biết thiếu niên ấy là hậu nhân được Nguyên Thanh sủng ái nhất, Thạch Hạo đổi ý, quyết ở lại để phá hỏng sự sắp đặt của kẻ thù và tranh thủ tài nguyên Tiên đạo. Vương Hi hạ điều kiện, mời hắn bình đẳng luận đạo thay vì làm người theo đuổi, rồi tuyển thêm một nam một nữ sơ đại trước khi dẫn cả đoàn vào thư viện. Bên trong sơn môn, Yêu Nguyệt công chúa công khai tuyên bố sau này cũng sẽ mời Thạch Hạo luận đạo, tiếp tục thế cạnh tranh với Vương Hi. Thạch Hạo còn đối diện uy thế của Lục Đà và chú ý tới Phong Hành Thiên, sẵn sàng quyết đấu sinh tử nếu xác nhận Phong tộc đứng sau việc hãm hại mình. Cuối cùng, hắn tiến vào Thiên Thần Thư Viện bằng một phương thức ngoài dự liệu, mở đầu cho những biến động mới."},{"chuong":1095,"tieuDe":"Thanh Hi U Lâm","tomTat":"Vương Hi đưa Thạch Hạo cùng đôi nam nữ mới được chọn tới Thanh Hi U Lâm, cho phép họ tu hành trong đạo thổ giàu thiên địa tinh hoa rồi giao Trần Dạ hướng dẫn trước khi rời đi gặp trưởng lão. Thạch Hạo vẫn dùng dung mạo cải biến và chủ động tránh tiếp xúc với cố nhân từ ba nghìn châu vì phải đề phòng Nguyên Thanh. Khi chọn thần nhạc làm nơi đặt chân, hắn liên tục hỏi chuyện bắt Ngân Thiên Ngô, Kim Sí Đại Bằng, Giao Long và Thanh Loan làm thức ăn, khiến Trần Dạ, Tô Lan cùng những người mới kinh hãi vì một số sinh linh là tọa kỵ của các thiên tài. Sau đó Thạch Hạo biến mất khỏi cảm ứng của mọi người, dùng tiên khí mở cửa đá và tiến vào tiểu thiên địa riêng của Vương Hi. Hắn ngồi lên một kỳ thạch có khả năng giúp hòa hợp thiên địa và nhanh chóng nhập ngộ đạo, nhưng không biết đó chính là chiếc giường Vương Hi mang từ Vương gia tới. Trần Dạ nổi giận còn Tô Lan xác nhận chưa từng có người khác đặt chân lên chiếc giường ấy. Khuê mật của công chúa Yêu Nguyệt liền cố ý hô lớn chuyện có người lên giường Vương Hi, khiến tin đồn lan rộng và báo trước rắc rối khi nàng trở về."},{"chuong":1096,"tieuDe":"Phong Ba","tomTat":"Tại Thanh Hi U Lâm, Thích Lâm cố ý tuyên bố Thạch Hạo đã lên giường của Vương Hi, khiến lời đồn nhanh chóng lan tới các đệ tử ở xa. Một nhóm đệ tử chính thức kéo đến truy hỏi, trong đó có người dùng đại thần thông khống chế tâm thần thiếu nữ đi theo Vương Hi và ép nàng đưa ra câu trả lời gây hiểu lầm. Tô Lan cùng Trần Nặc liên tục giải thích nhưng không thể ngăn tin tức bị thêm thắt và biến dạng, làm danh tiếng của Vương Hi chịu ảnh hưởng nghiêm trọng. Thạch Hạo phủ nhận sự xuyên tạc, sau đó công khai mắng và đe dọa đập chết những kẻ cố tình gây chuyện. Vương Hi nghe tin liền trở lại Thanh Hi U Lâm, nhưng đã kiềm chế ý định trừng trị Thạch Hạo và chỉ đứng im quan sát cục diện. Cuối cùng, Thạch Hạo bước tới hỏi thẳng nàng liệu mình có thể đập chết đám người đang gây chuyện ngay tại đây hay không."},{"chuong":1097,"tieuDe":"Cực Phẩm","tomTat":"Vương Hi nhắc quy định cấm đệ tử chính thức của Thiên Thần Thư Viện tự giết lẫn nhau, nhưng Thạch Hạo cố ý vin vào thân phận của mình để tiếp tục khiêu khích đám đông. Hắn chế nhạo hậu duệ Thái cổ ma hùng và chỉ đồng ý giao đấu nếu đối phương đưa ra thiên tài địa bảo đủ giá trị làm tiền cược. Ma hùng lấy một lò Tử Phủ dịch màu tím bốc sương mù ngũ sắc, khiến Thạch Hạo chấp nhận trận đấu. Khi giao chiến, Thạch Hạo dùng cực tốc né một đạo tiên khí, áp sát rồi đánh ma hùng bay xa và ho ra máu. Chiến thắng tay không trước một đệ tử chính thức sở hữu tiên khí khiến những người chứng kiến vô cùng kinh ngạc. Thạch Hạo lấy cả lò Tử Phủ dịch làm chiến lợi phẩm và tiếp tục mời những người khác tỷ thí nếu họ có bảo vật quý. Vương Hi nhận định hắn sẽ sớm nổi danh và sự hiện diện của hắn sẽ khiến Thiên Thần Thư Viện khó còn yên tĩnh."},{"chuong":1098,"tieuDe":"Thu Hoàng Huyết","tomTat":"Thạch Hạo trở vào động phủ của Vương Hi, kiểm tra một lò Tử Phủ dịch tỏa sương ngũ sắc và xác nhận vật này rất bất phàm dù chưa thai nghén thành tiên khí. Một con Xuyên Sơn Giáp màu bạc tới khiêu chiến, mang một đoàn Hoàng huyết làm tiền cược rồi dùng tiên khí hộ thể cùng thần thuật huyết mạch để xuyên phá hư không và cắn giết. Thạch Hạo không vận dụng hai đạo tiên khí mà dựa vào thể phách, bộ pháp và khả năng nhìn thấu các tiết điểm vận chuyển Cốt văn để đánh đối thủ trọng thương. Sau chiến thắng ấy, hắn tuyên bố chỉ nhận Hoàng huyết làm cược và liên tiếp đánh bại nhiều đệ tử khác trong hai ngày, nâng số bảo huyết đang giữ lên gần mười đoàn. Các đệ tử thất bại tìm cách mời những cao thủ đang bế quan như Nhiễm Long và Ma Cưu ra tay, còn Vương Hi phóng uy thế buộc đám người gây sự rời khỏi động phủ. Thạch Hạo dự định dùng Hoàng huyết để gột rửa thân thể và thực hiện Đại Niết bàn. Khi Vương Hi đề nghị hắn tăng tu vi để cùng tới Tiên gia chiến trường, hắn ban đầu không mấy hứng thú nhưng lập tức cân nhắc tham gia sau khi biết Lục Đà, Phong Hành Thiên cùng nhiều cao thủ khác cũng có thể xuất hiện tại đó."},{"chuong":1099,"tieuDe":"Đại Lực Trợ Giúp","tomTat":"Vương Hi giới thiệu Tiên gia chiến trường là nơi chân tiên từng giao chiến, còn lưu kinh văn Tiên đạo, sinh vật kỳ dị và những khe nứt hư không có thể nối sang một thế giới khác. Thiên Thần Thư Viện yêu cầu đệ tử lập chiến tích để đổi lấy kinh văn, còn Thạch Hạo dự định nhân cơ hội tranh phong với các thiên tài và thanh toán Phong Hành Thiên cùng hậu nhân Nguyên Thanh. Vương Hi cho hắn mượn những kinh thư nguyên bản khắc trên xương và ngọc, qua đó khiến hắn nảy sinh chí hướng khai sáng một hệ thống tu luyện mới. Khi tìm thấy cổ pháp dùng chân huyết tối cao phối hợp dược thảo để gột rửa thân thể và Nguyên Thần, Thạch Hạo liên tiếp đánh bại người khiêu chiến và tích lũy mười bốn phần Chân Hoàng huyết. Vương Hi tặng thêm sáu phần hoàng huyết, sai Tô Lan và Trần Nặc lấy đủ dược thảo, đổi lại mong hắn trợ chiến tại Tiên gia chiến trường. Sau mười ngày luyện hóa, Thạch Hạo làm nhà đá nứt vỡ và khiến đóa đại đạo thứ hai nở rộ trên đầu, tỏa ra khí tức đại đạo đáng sợ."},{"chuong":1100,"tieuDe":"Người Đần Độn","tomTat":"Thạch Hạo kết thúc bế quan, tu thành đóa Đại đạo chi hoa thứ hai và cảm nhận thực lực tăng lên rõ rệt, dù trong hoa vẫn chưa dựng dục sinh linh. Hai mươi đoàn Chân Hoàng huyết đã hỗ trợ quá trình tu luyện nhưng không đủ để hắn tắm rửa toàn thân và hoàn thành Đại Niết bàn như Lục Đà, Yêu Nguyệt hay Huyền Côn. Vương Hi đến báo rằng Thiên Thần Thư Viện vẫn đang chuẩn bị cho chuyến tiến vào tiên gia chiến trường và dặn hắn tiếp tục củng cố tu vi. Không muốn tiếp tục tiềm tu, Thạch Hạo hỏi Tô Lan và Trần Nặc về Thần dược viên cùng danh sách những người còn giữ Hoàng huyết, dự định dùng Hoàng huyết làm tiền cược trong các trận luận bàn. Bị hai người từ chối, hắn chuyển sang nhắm tới Thích Lâm, người từng tung tin làm tổn hại danh dự của hắn. Thạch Hạo lập luận rằng Vương Hi không tiện trực tiếp đối đầu với phe Yêu Nguyệt nên cần hắn tạo cớ ra tay, khiến Tô Lan và Trần Nặc cuối cùng đồng ý dẫn đường đi tìm Thích Lâm."}];
